import { useState, useEffect } from 'react';

interface Workflow {
  id: string;
  name: string;
  description: string;
}

export function VisualWorkflowEditor() {
  const [workflows, setWorkflows] = useState<Workflow[]>([]);
  const [newWorkflowName, setNewWorkflowName] = useState('');
  const [newWorkflowDescription, setNewWorkflowDescription] = useState('');

  useEffect(() => {
    fetch('/api/workflow-execution-engine/workflows')
      .then(res => res.json())
      .then(setWorkflows)
      .catch(err => console.error('Failed to fetch workflows:', err));
  }, []);

  const handleCreateWorkflow = () => {
    if (!newWorkflowName.trim()) return;

    fetch('/api/workflow-execution-engine/workflows', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: newWorkflowName,
        description: newWorkflowDescription
      })
    })
    .then(res => res.json())
    .then(newWorkflow => {
      setWorkflows([...workflows, newWorkflow]);
      setNewWorkflowName('');
      setNewWorkflowDescription('');
    })
    .catch(err => console.error('Failed to create workflow:', err));
  };

  const handleDeleteWorkflow = (id: string) => {
    fetch(`/api/workflow-execution-engine/workflows/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setWorkflows(workflows.filter(w => w.id !== id));
    })
    .catch(err => console.error('Failed to delete workflow:', err));
  };

  return (
    <div className="visual-workflow-editor">
      <h1>Visual Workflow Editor</h1>

      <div className="create-workflow-form">
        <input
          type="text"
          placeholder="Workflow name"
          value={newWorkflowName}
          onChange={(e) => setNewWorkflowName(e.target.value)}
        />
        <input
          type="text"
          placeholder="Description"
          value={newWorkflowDescription}
          onChange={(e) => setNewWorkflowDescription(e.target.value)}
        />
        <button onClick={handleCreateWorkflow}>Create Workflow</button>
      </div>

      <div className="workflow-list">
        <h2>Existing Workflows</h2>
        {workflows.length === 0 ? (
          <p>No workflows found.</p>
        ) : (
          <ul>
            {workflows.map(workflow => (
              <li key={workflow.id}>
                <span>{workflow.name}</span>
                <span>{workflow.description}</span>
                <button onClick={() => handleDeleteWorkflow(workflow.id)}>Delete</button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Photo {
  id: number;
  filename: string;
  owner_id: number;
}

interface Comment {
  id: number;
  photoId: number;
  authorId: number;
  commentText: string;
  timestamp: string;
}

export function PhotoGallery() {
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState({
    photoId: 0,
    authorId: 0,
    commentText: '',
  });

  useEffect(() => {
    fetch('/api/photos-api/')
      .then(res => res.json())
      .then(data => setPhotos(data));

    fetch('/api/photos-api/comments')
      .then(res => res.json())
      .then(data => setComments(data));
  }, []);

  const handleAddComment = () => {
    fetch('/api/comment-service/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        photoId: newComment.photoId,
        authorId: newComment.authorId,
        commentText: newComment.commentText,
        timestamp: new Date().toISOString(),
      }),
    })
      .then(res => res.json())
      .then(comment => {
        setComments([...comments, comment]);
        setNewComment({ photoId: 0, authorId: 0, commentText: '' });
      });
  };

  const handleDeletePhoto = (id: number) => {
    fetch(`/api/delete-guard/${id}`, { method: 'DELETE' });
    setPhotos(photos.filter(photo => photo.id !== id));
  };

  return (
    <div>
      <h1>Family Photo Gallery</h1>
      <div className="photo-grid">
        {photos.map(photo => (
          <div key={photo.id} className="photo-card">
            <img src={`/images/${photo.filename}`} alt={photo.filename} />
            <button onClick={() => handleDeletePhoto(photo.id)}>Delete</button>
          </div>
        ))}
      </div>

      <div className="comment-section">
        <h2>Add Comment</h2>
        <input
          type="number"
          placeholder="Photo ID"
          value={newComment.photoId}
          onChange={e => setNewComment({...newComment, photoId: Number(e.target.value)})}
        />
        <input
          type="number"
          placeholder="Author ID"
          value={newComment.authorId}
          onChange={e => setNewComment({...newComment, authorId: Number(e.target.value)})}
        />
        <input
          type="text"
          placeholder="Comment Text"
          value={newComment.commentText}
          onChange={e => setNewComment({...newComment, commentText: e.target.value})}
        />
        <button onClick={handleAddComment}>Post Comment</button>
      </div>

      <div className="comments-list">
        <h2>Comments</h2>
        {comments.map(comment => (
          <div key={comment.id} className="comment">
            <p>{comment.commentText}</p>
            <small>By user {comment.authorId} on photo {comment.photoId}</small>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

export function DesignCanvas() {
  const [designId, setDesignId] = useState<string | null>(null);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Load existing design or create new one
  useEffect(() => {
    const fetchOrCreateDesign = async () => {
      setIsLoading(true);
      try {
        // Try to get existing design
        const response = await fetch('/api/design-collaboration-service/');
        if (response.ok) {
          const data = await response.json();
          setDesignId(data.id);
          setTitle(data.name);
          setContent(data.content);
        } else {
          // Create new design
          const createResponse = await fetch('/api/design-collaboration-service/', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              name: 'Untitled Design',
              content: '',
            }),
          });
          if (createResponse.ok) {
            const newDesign = await createResponse.json();
            setDesignId(newDesign.id);
            setTitle(newDesign.name);
            setContent(newDesign.content);
          }
        }
      } catch (error) {
        console.error('Failed to load or create design:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchOrCreateDesign();
  }, []);

  const handleSave = async () => {
    if (!designId) return;

    try {
      const response = await fetch(`/api/design-collaboration-service/${designId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: title,
          content,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to save design');
      }
    } catch (error) {
      console.error('Error saving design:', error);
    }
  };

  const handleDelete = async () => {
    if (!designId) return;

    try {
      const response = await fetch(`/api/design-collaboration-service/${designId}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete design');
      }

      setDesignId(null);
      setTitle('');
      setContent('');
    } catch (error) {
      console.error('Error deleting design:', error);
    }
  };

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="design-canvas">
      <header>
        <h1>Design Canvas</h1>
        <div className="canvas-controls">
          <input
            type="text"
            placeholder="Design Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="design-title-input"
          />
          <button onClick={handleSave} className="save-button">Save</button>
          <button onClick={handleDelete} className="delete-button">Delete</button>
        </div>
      </header>

      <main className="canvas-content">
        <div className="layout-tools">
          <h2>Layout Tools</h2>
          <p>Responsive layout controls would appear here.</p>
        </div>

        <div className="canvas-editor">
          <textarea
            placeholder="Design content goes here..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="design-content-textarea"
          />
        </div>

        <div className="code-inspection-mode">
          <h2>Code Inspection Mode</h2>
          <p>Code inspection tools would appear here.</p>
        </div>
      </main>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface StockItem {
  id: number;
  name: string;
  quantity: number;
  unit: string;
  expiry_date: string;
  last_consumed: string;
}

export function StockDashboard() {
  const [stockItems, setStockItems] = useState<StockItem[]>([]);
  const [newItem, setNewItem] = useState({
    name: '',
    quantity: 0,
    unit: '',
    expiry_date: '',
    last_consumed: ''
  });

  useEffect(() => {
    fetchStock();
  }, []);

  const fetchStock = async () => {
    try {
      const response = await fetch('/api/household-api/stock');
      const data = await response.json();
      setStockItems(data);
    } catch (error) {
      console.error('Failed to fetch stock:', error);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/household-api/stock', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(newItem)
      });
      const createdItem = await response.json();
      setStockItems([...stockItems, createdItem]);
      setNewItem({
        name: '',
        quantity: 0,
        unit: '',
        expiry_date: '',
        last_consumed: ''
      });
    } catch (error) {
      console.error('Failed to add item:', error);
    }
  };

  const handleDeleteItem = async (id: number) => {
    try {
      await fetch(`/api/household-api/stock/${id}`, {
        method: 'DELETE'
      });
      setStockItems(stockItems.filter(item => item.id !== id));
    } catch (error) {
      console.error('Failed to delete item:', error);
    }
  };

  return (
    <div className="stock-dashboard">
      <h1>Household Stock Dashboard</h1>

      <div className="stock-list">
        <h2>Current Stock</h2>
        <ul>
          {stockItems.map(item => (
            <li key={item.id}>
              <span>{item.name} - {item.quantity} {item.unit}</span>
              <span>Expires: {item.expiry_date}</span>
              <button onClick={() => handleDeleteItem(item.id)}>Remove</button>
            </li>
          ))}
        </ul>
      </div>

      <div className="add-item">
        <h2>Add New Item</h2>
        <form onSubmit={handleAddItem}>
          <input
            type="text"
            placeholder="Item Name"
            value={newItem.name}
            onChange={(e) => setNewItem({...newItem, name: e.target.value})}
            required
          />
          <input
            type="number"
            placeholder="Quantity"
            value={newItem.quantity || ''}
            onChange={(e) => setNewItem({...newItem, quantity: Number(e.target.value)})}
            required
          />
          <input
            type="text"
            placeholder="Unit (e.g., kg, pcs)"
            value={newItem.unit}
            onChange={(e) => setNewItem({...newItem, unit: e.target.value})}
            required
          />
          <input
            type="date"
            placeholder="Expiry Date"
            value={newItem.expiry_date}
            onChange={(e) => setNewItem({...newItem, expiry_date: e.target.value})}
            required
          />
          <input
            type="date"
            placeholder="Last Consumed"
            value={newItem.last_consumed}
            onChange={(e) => setNewItem({...newItem, last_consumed: e.target.value})}
            required
          />
          <button type="submit">Add Item</button>
        </form>
      </div>

      <div className="shopping-list">
        <h2>Shopping List</h2>
        <p>Items below threshold will appear here.</p>
      </div>

      <div className="barcode-scanner">
        <h2>Scan Barcode</h2>
        <p>Point your camera at a product barcode to add it to stock.</p>
      </div>
    </div>
  );
}

