    .then(res => res.json())
    .then(photo => {
      setPhotos([...photos, photo]);
      setNewPhoto({ filename: '', owner_id: 0, url: '', caption: '' });
    });
  };

  const handleAddComment = () => {
    fetch('/api/comment-service/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        photoId: newComment.photoId,
        authorId: newComment.authorId,
        commentText: newComment.commentText,
        timestamp: newComment.timestamp
      })
    })
    .then(res => res.json())
    .then(comment => {
      setComments([...comments, comment]);
      setNewComment({ photoId: 0, authorId: 0, commentText: '', timestamp: new Date().toISOString() });
    });
  };

  const handleDeletePhoto = (id: number) => {
    fetch(`/api/photos-api/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setPhotos(photos.filter(photo => photo.id !== id));
    });
  };

  return (
    <div>
      <h1>Family Photo Album</h1>

      <div>
        <h2>Add New Photo</h2>
        <input
          type="text"
          placeholder="Filename"
          value={newPhoto.filename}
          onChange={(e) => setNewPhoto({...newPhoto, filename: e.target.value})}
        />
        <input
          type="number"
          placeholder="Owner ID"
          value={newPhoto.owner_id}
          onChange={(e) => setNewPhoto({...newPhoto, owner_id: Number(e.target.value)})}
        />
        <input
          type="text"
          placeholder="URL"
          value={newPhoto.url}
          onChange={(e) => setNewPhoto({...newPhoto, url: e.target.value})}
        />
        <input
          type="text"
          placeholder="Caption"
          value={newPhoto.caption}
          onChange={(e) => setNewPhoto({...newPhoto, caption: e.target.value})}
        />
        <button onClick={handleAddPhoto}>Add Photo</button>
      </div>

      <div>
        <h2>Add Comment</h2>
        <input
          type="number"
          placeholder="Photo ID"
          value={newComment.photoId}
          onChange={(e) => setNewComment({...newComment, photoId: Number(e.target.value)})}
        />
        <input
          type="number"
          placeholder="Author ID"
          value={newComment.authorId}
          onChange={(e) => setNewComment({...newComment, authorId: Number(e.target.value)})}
        />
        <input
          type="text"
          placeholder="Comment Text"
          value={newComment.commentText}
          onChange={(e) => setNewComment({...newComment, commentText: e.target.value})}
        />
        <button onClick={handleAddComment}>Add Comment</button>
