import { useState, useEffect } from 'react';

interface Server {
  id: number;
  name: string;
  ownerId: string;
  config: {
    gameType: string;
    port: number;
  };
  status: 'running' | 'stopped';
}

export function ServerManagementDashboard() {
  const [servers, setServers] = useState<Server[]>([]);
  const [newServerName, setNewServerName] = useState('');
  const [newServerGameType, setNewServerGameType] = useState('');
  const [newServerPort, setNewServerPort] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchServers();
  }, []);

  const fetchServers = async () => {
    try {
      const response = await fetch('/api/server-orchestration-daemon/servers');
      const data = await response.json();
      setServers(data);
      setLoading(false);
    } catch (error) {
      console.error('Failed to fetch servers:', error);
      setLoading(false);
    }
  };

  const handleCreateServer = async (e: React.FormEvent) => {
    e.preventDefault();

    const newServer = {
      name: newServerName,
      ownerId: 'current-user-id', // This should come from auth context
      config: {
        gameType: newServerGameType,
        port: Number(newServerPort),
      },
    };

    try {
      const response = await fetch('/api/server-orchestration-daemon/servers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newServer),
      });

      if (response.ok) {
        const createdServer = await response.json();
        setServers([...servers, createdServer]);
        setNewServerName('');
        setNewServerGameType('');
        setNewServerPort('');
      }
    } catch (error) {
      console.error('Failed to create server:', error);
    }
  };

  const handleStartServer = async (id: number) => {
    try {
      const response = await fetch(`/api/server-orchestration-daemon/servers/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: servers.find(s => s.id === id)?.name || '',
          ownerId: 'current-user-id',
          config: servers.find(s => s.id === id)?.config || { gameType: '', port: 0 },
          action: 'start',
        }),
      });

      if (response.ok) {
        const updatedServer = await response.json();
        setServers(servers.map(server => server.id === id ? updatedServer : server));
      }
    } catch (error) {
      console.error('Failed to start server:', error);
    }
  };

  const handleStopServer = async (id: number) => {
    try {
      const response = await fetch(`/api/server-orchestration-daemon/servers/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: servers.find(s => s.id === id)?.name || '',
          ownerId: 'current-user-id',
          config: servers.find(s => s.id === id)?.config || { gameType: '', port: 0 },
          action: 'stop',
        }),
      });

      if (response.ok) {
        const updatedServer = await response.json();
        setServers(servers.map(server => server.id === id ? updatedServer : server));
      }
    } catch (error) {
      console.error('Failed to stop server:', error);
    }
  };

  const handleDeleteServer = async (id: number) => {
    try {
      const response = await fetch(`/api/server-orchestration-daemon/servers/${id}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        setServers(servers.filter(server => server.id !== id));
      }
    } catch (error) {
      console.error('Failed to delete server:', error);
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>Server Management Dashboard</h1>

      <form onSubmit={handleCreateServer}>
        <input
          type="text"
          placeholder="Server Name"
          value={newServerName}
          onChange={(e) => setNewServerName(e.target.value)}
          required
        />
        <input
          type="text"
          placeholder="Game Type"
          value={newServerGameType}
          onChange={(e) => setNewServerGameType(e.target.value)}
          required
        />
        <input
          type="number"
          placeholder="Port"
          value={newServerPort}
          onChange={(e) => setNewServerPort(e.target.value)}
          required
        />
        <button type="submit">Create Server</button>
      </form>

      <h2>Servers</h2>
      <ul>
        {servers.map(server => (
          <li key={server.id}>
            <span>{server.name} ({server.config.gameType}:{server.config.port}) - {server.status}</span>
            <button onClick={() => handleStartServer(server.id)}>Start</button>
            <button onClick={() => handleStopServer(server.id)}>Stop</button>
            <button onClick={() => handleDeleteServer(server.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Walk {
  id: number;
  ownerId: number;
  walkerId: number;
  date: string;
  status: 'pending' | 'accepted' | 'declined';
}

export function WalkBookingView() {
  const [walks, setWalks] = useState<Walk[]>([]);
  const [newWalk, setNewWalk] = useState({
    ownerId: 1,
    walkerId: 1,
    date: '',
    status: 'pending' as 'pending',
  });

  useEffect(() => {
    fetch('/api/walks-api/')
      .then(res => res.json())
      .then(data => setWalks(data));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewWalk({
      ...newWalk,
      [name]: value,
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    fetch('/api/walks-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newWalk),
    })
      .then(res => res.json())
      .then(data => {
        setWalks([...walks, data]);
        setNewWalk({
          ownerId: 1,
          walkerId: 1,
          date: '',
          status: 'pending',
        });
      });
  };

  const handleDelete = (id: number) => {
    fetch(`/api/walks-api/${id}`, { method: 'DELETE' })
      .then(() => setWalks(walks.filter(walk => walk.id !== id)));
  };

  return (
    <div>
      <h1>Walk Booking</h1>
      <form onSubmit={handleSubmit}>
