          required
        />
        <button type="submit">Book Walk</button>
      </form>
      <ul>
        {walks.map(walk => (
          <li key={walk.id}>
            {walk.date} - {walk.status}
            <button onClick={() => handleDelete(walk.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useState } from 'react';

interface Book {
  id: number;
  title: string;
  price: number;
  sellerId: number;
  payoutStatus: string;
}

export function StaffOnlyPayoutQueue() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/books-api/')
      .then(response => response.json())
      .then(data => {
        // Filter books that are awaiting staff approval for payout
        const filteredBooks = data.filter((book: Book) => book.payoutStatus === 'pending');
        setBooks(filteredBooks);
        setLoading(false);
      });
  }, []);

  const handleApprove = (id: number) => {
    // Update the payout status to approved
    fetch(`/api/books-api/${id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        id,
        title: books.find(book => book.id === id)?.title || '',
        price: books.find(book => book.id === id)?.price || 0,
        sellerId: books.find(book => book.id === id)?.sellerId || 0,
        payoutStatus: 'approved'
      }),
    });

    // Remove the book from the queue
    setBooks(books.filter(book => book.id !== id));
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>Staff-Only Payout Queue</h1>
      <ul>
        {books.map(book => (
          <li key={book.id}>
            <span>{book.title} - ${book.price}</span>
            <button onClick={() => handleApprove(book.id)}>Approve</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

