export function AdminAllocationPanel() {
  const [members, setMembers] = useState<CoOpMember[]>([]);
  const [newMember, setNewMember] = useState<Omit<CoOpMember, 'id'>>({ 
    name: '', 
    email: '', 
    energy_quota: 0 
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Partial<CoOpMember>>({});

  useEffect(() => {
    fetch('/api/co-op-allocation-api/')
      .then(res => res.json())
      .then(data => setMembers(data));
  }, []);

  const handleAddMember = () => {
    fetch('/api/co-op-allocation-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newMember)
    })
      .then(res => res.json())
      .then(member => {
        setMembers([...members, member]);
        setNewMember({ name: '', email: '', energy_quota: 0 });
      });
  };

  const handleUpdateMember = () => {
    if (editingId === null) return;

    fetch(`/api/co-op-allocation-api/${editingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: editForm.name,
        energy_quota: editForm.energy_quota
      })
    })
      .then(res => res.json())
      .then(updatedMember => {
        setMembers(members.map(m => m.id === editingId ? updatedMember : m));
        setEditingId(null);
        setEditForm({});
      });
  };

  const handleDeleteMember = (id: number) => {
    fetch(`/api/co-op-allocation-api/${id}`, { method: 'DELETE' })
      .then(() => setMembers(members.filter(m => m.id !== id)));
  };

  return (
