        />
        <input
          type="email"
          placeholder="Email"
          value={newMember.email}
          onChange={e => setNewMember({...newMember, email: e.target.value})}
        />
        <input
          type="number"
          placeholder="Energy Quota"
          value={newMember.energy_quota}
          onChange={e => setNewMember({...newMember, energy_quota: Number(e.target.value)})}
        />
        <button onClick={handleAddMember}>Add Member</button>
      </div>

      <h2>Manage Members</h2>
      <ul>
        {members.map(member => (
          <li key={member.id}>
            {editingId === member.id ? (
              <div>
                <input
                  type="text"
                  value={editForm.name || ''}
                  onChange={e => setEditForm({...editForm, name: e.target.value})}
