import { useState } from 'react';

interface Machine {
  id: number;
  name: string;
  status: string;
}

export function MachineReportForm() {
  const [selectedMachineId, setSelectedMachineId] = useState<number | null>(null);
  const [reportTimestamp, setReportTimestamp] = useState<string>('');
  const [status, setStatus] = useState<string>('');

  // Fetch machines data
  const fetchMachines = async () => {
    const response = await fetch('/api/machines-api/machines');
    const machines: Machine[] = await response.json();
    return machines;
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedMachineId === null || !reportTimestamp || !status) {
      alert('Please fill in all fields');
      return;
    }

    try {
      const response = await fetch(`/api/machines-api/machines/${selectedMachineId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          status,
          reportTimestamp,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update machine status');
      }

      // Reset form after successful submission
      setSelectedMachineId(null);
      setReportTimestamp('');
      setStatus('');

      alert('Machine reported successfully!');
    } catch (error) {
      console.error('Error reporting machine:', error);
      alert('Failed to report machine. Please try again.');
    }
  };

  return (
    <div>
      <h2>Report Broken Machine</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="machineSelect">Select Machine:</label>
          <select
            id="machineSelect"
            value={selectedMachineId ?? ''}
            onChange={(e) => setSelectedMachineId(Number(e.target.value))}
          >
            <option value="">-- Select a machine --</option>
            {fetchMachines().then(machines => 
              machines.map(machine => (
                <option key={machine.id} value={machine.id}>
                  {machine.name}
                </option>
              ))
            )}
          </select>
        </div>

        <div>
          <label htmlFor="reportTimestamp">Report Timestamp:</label>
          <input
            type="datetime-local"
            id="reportTimestamp"
            value={reportTimestamp}
            onChange={(e) => setReportTimestamp(e.target.value)}
          />
        </div>

        <div>
          <label htmlFor="status">Status:</label>
          <input
            type="text"
            id="status"
            value={status}
            onChange={(e) => setStatus(e.target.value)}
          />
        </div>

        <button type="submit">Submit Report</button>
      </form>
    </div>
  );
}

