export function InventoryDashboard() {
  const [kegs, setKegs] = useState<Keg[]>([]);
  const [newKegStyle, setNewKegStyle] = useState('');
  const [newKegQuantity, setNewKegQuantity] = useState('');
  const [editingKegId, setEditingKegId] = useState<number | null>(null);
  const [editStyle, setEditStyle] = useState('');
  const [editQuantity, setEditQuantity] = useState('');

  useEffect(() => {
    fetch('/api/inventory-api/')
      .then(res => res.json())
      .then(data => setKegs(data));
  }, []);

  const handleAddKeg = () => {
    if (!newKegStyle || !newKegQuantity) return;

    fetch('/api/inventory-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        style: newKegStyle,
        quantity: Number(newKegQuantity)
      })
    })
    .then(res => res.json())
    .then(addedKeg => {
      setKegs([...kegs, addedKeg]);
      setNewKegStyle('');
      setNewKegQuantity('');
    });
  };

  const handleUpdateKeg = () => {
    if (editingKegId === null || !editStyle || !editQuantity) return;

    fetch(`/api/inventory-api/${editingKegId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        style: editStyle,
        quantity: Number(editQuantity)
      })
    })
    .then(res => res.json())
    .then(updatedKeg => {
      setKegs(kegs.map(k => k.id === editingKegId ? updatedKeg : k));
      setEditingKegId(null);
      setEditStyle('');
      setEditQuantity('');
    });
  };

  const handleDeleteKeg = (id: number) => {
    fetch(`/api/inventory-api/${id}`, { method: 'DELETE' })
      .then(() => setKegs(kegs.filter(k => k.id !== id)));
  };

  return (
    <div>
