          {kegs.map(keg => (
            <li key={keg.id}>
              {editingKegId === keg.id ? (
                <>
                  <input
                    type="text"
                    value={editStyle}
                    onChange={(e) => setEditStyle(e.target.value)}
                  />
                  <input
                    type="number"
                    value={editQuantity}
                    onChange={(e) => setEditQuantity(e.target.value)}
                  />
                  <button onClick={handleUpdateKeg}>Save</button>
                </>
              ) : (
                <>
                  {keg.style}: {keg.quantity} units
                  <button onClick={() => {
                    setEditingKegId(keg.id);
                    setEditStyle(keg.style);
                    setEditQuantity(keg.quantity.toString());
                  }}>Edit</button>
                  <button onClick={() => handleDeleteKeg(keg.id)}>Remove</button>
                </>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
