      .then(data => {
        // Extract unique equipment IDs from checkouts
        const equipmentIds = [...new Set(data.map((item: CheckoutItem) => item.equipmentId))];
        // Fetch equipment details for each ID
        Promise.all(
          equipmentIds.map(id => 
            fetch(`/api/checkout-api/${id}`)
              .then(res => res.json())
          )
        ).then(equipmentData => {
          setEquipmentList(equipmentData);
        });
      });
  }, []);

  const handleCheckout = () => {
    if (selectedEquipmentId === 0 || userId === 0) return;

    fetch('/api/checkout-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        equipmentId: selectedEquipmentId,
        userId: userId,
        checkoutDate: checkoutDate || new Date().toISOString(),
        returnDate: returnDate || null
      })
    })
    .then(response => response.json())
    .then(newCheckout => {
      setCheckouts([...checkouts, newCheckout]);
      // Reset form
      setSelectedEquipmentId(0);
      setUserId(0);
      setCheckoutDate('');
      setReturnDate('');
    });
  };

  const handleReturn = (id: number) => {
    fetch(`/api/checkout-api/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        equipmentId: checkouts.find(c => c.id === id)?.equipmentId || 0,
        userId: checkouts.find(c => c.id === id)?.userId || 0,
        checkoutDate: checkouts.find(c => c.id === id)?.checkoutDate || '',
        returnDate: new Date().toISOString()
      })
    })
    .then(response => response.json())
    .then(updatedCheckout => {
      setCheckouts(checkouts.map(c => c.id === id ? updatedCheckout : c));
    });
  };

  return (
    <div>
      <h1>Checkout Queue</h1>
      <div>
        <h2>Checked Out Items</h2>
        <ul>
          {checkouts.map(item => (
            <li key={item.id}>
              Equipment ID: {item.equipmentId}, User ID: {item.userId},
              Checked Out: {item.checkoutDate}, Return Date: {item.returnDate}
              <button onClick={() => handleReturn(item.id)}>Mark as Returned</button>
            </li>
          ))}
        </ul>
      </div>
      <div>
        <h2>Check Out New Item</h2>
        <div>
          <label>
            Equipment ID:
            <input 
              type="number" 
              value={selectedEquipmentId}
              onChange={(e) => setSelectedEquipmentId(Number(e.target.value))}
            />
          </label>
        </div>
        <div>
          <label>
            User ID:
            <input 
              type="number" 
              value={userId}
              onChange={(e) => setUserId(Number(e.target.value))}
            />
          </label>
        </div>
        <div>
          <label>
            Checkout Date:
            <input 
              type="date" 
              value={checkoutDate}
              onChange={(e) => setCheckoutDate(e.target.value)}
            />
          </label>
        </div>
        <div>
          <label>
            Return Date:
            <input 
              type="date" 
              value={returnDate}
              onChange={(e) => setReturnDate(e.target.value)}
            />
          </label>
        </div>
        <button onClick={handleCheckout}>Check Out</button>
      </div>
    </div>
  );
}

