import { useState, useEffect } from 'react';

interface CommerceRecord {
  id: string;
  type: string;
  data: string;
}

export function CustomStorefront() {
  const [records, setRecords] = useState<CommerceRecord[]>([]);
  const [newType, setNewType] = useState('');
  const [newData, setNewData] = useState('');

  useEffect(() => {
    fetch('/api/commerce-api/commerce-records')
      .then(res => res.json())
      .then(setRecords);
  }, []);

  const handleAddRecord = () => {
    if (!newType || !newData) return;

    fetch('/api/commerce-api/commerce-records', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: newType, data: newData })
    })
    .then(res => res.json())
    .then(newRecord => {
      setRecords([...records, newRecord]);
      setNewType('');
      setNewData('');
    });
  };

  const handleDeleteRecord = (id: string) => {
    fetch(`/api/commerce-api/commerce-records/${id}`, { method: 'DELETE' })
      .then(() => {
        setRecords(records.filter(record => record.id !== id));
      });
  };

  return (
    <div>
      <h1>Custom Storefront</h1>
      <div>
        <input
          type="text"
          placeholder="Type"
          value={newType}
          onChange={e => setNewType(e.target.value)}
        />
        <input
          type="text"
          placeholder="Data"
          value={newData}
          onChange={e => setNewData(e.target.value)}
        />
        <button onClick={handleAddRecord}>Add Record</button>
      </div>
      <ul>
        {records.map(record => (
          <li key={record.id}>
            {record.type}: {record.data}
            <button onClick={() => handleDeleteRecord(record.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Device {
  id: number;
  name: string;
  type: string;
  status: boolean;
}

export function DeviceDashboard() {
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/automation-engine/')
      .then(response => response.json())
      .then(data => {
        setDevices(data);
        setLoading(false);
      });
  }, []);

  const toggleDevice = (id: number, currentStatus: boolean) => {
    fetch(`/api/automation-engine/${id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        deviceId: id,
        state: !currentStatus,
        timestamp: new Date().toISOString()
      })
    })
    .then(response => response.json())
    .then(updatedDevice => {
      setDevices(devices.map(device => 
        device.id === id ? { ...device, status: updatedDevice.state } : device
      ));
    });
  };

  const addDevice = () => {
    const newDevice = {
      name: 'New Device',
      type: 'Generic',
      status: false
    };

    fetch('/api/automation-engine/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        deviceId: 0,
        state: false,
        timestamp: new Date().toISOString(),
        ...newDevice
      })
    })
    .then(response => response.json())
    .then(createdDevice => {
      setDevices([...devices, createdDevice]);
    });
  };

  const deleteDevice = (id: number) => {
    fetch(`/api/automation-engine/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setDevices(devices.filter(device => device.id !== id));
    });
  };

  if (loading) {
    return <div>Loading devices...</div>;
  }

  return (
    <div>
      <h1>Device Dashboard</h1>
      <button onClick={addDevice}>Add New Device</button>
      <div>
        {devices.map(device => (
          <div key={device.id}>
            <span>{device.name} ({device.type})</span>
            <input
              type="checkbox"
              checked={device.status}
              onChange={() => toggleDevice(device.id, device.status)}
            />
            <button onClick={() => deleteDevice(device.id)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';

interface Room {
  id: number;
  room_number: string;
  status: 'clean' | 'dirty' | 'occupied' | 'maintenance';
  assigned_housekeeper_id?: number;
}

export function RoomStatusBoard() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/housekeeping-api/rooms')
      .then(response => response.json())
      .then(data => {
        setRooms(data);
        setLoading(false);
      });
  }, []);

  const updateRoomStatus = (roomId: number, newStatus: Room['status']) => {
    fetch(`/api/housekeeping-api/rooms/${roomId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        status: newStatus,
        assigned_housekeeper_id: rooms.find(r => r.id === roomId)?.assigned_housekeeper_id || null,
      }),
    });
  };

  if (loading) {
    return <div>Loading rooms...</div>;
  }

  return (
    <div>
      <h1>Room Status Board</h1>
      <table>
        <thead>
          <tr>
            <th>Room Number</th>
            <th>Status</th>
            <th>Assigned Housekeeper ID</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {rooms.map(room => (
            <tr key={room.id}>
              <td>{room.room_number}</td>
              <td>
                <select
                  value={room.status}
                  onChange={(e) => updateRoomStatus(room.id, e.target.value as Room['status'])}
                >
                  <option value="clean">Clean</option>
                  <option value="dirty">Dirty</option>
                  <option value="occupied">Occupied</option>
                  <option value="maintenance">Maintenance</option>
                </select>
              </td>
              <td>
                <input
                  type="number"
                  value={room.assigned_housekeeper_id || ''}
                  onChange={(e) => {
                    const newId = e.target.value ? Number(e.target.value) : null;
                    fetch(`/api/housekeeping-api/rooms/${room.id}`, {
                      method: 'PUT',
                      headers: {
                        'Content-Type': 'application/json',
                      },
                      body: JSON.stringify({
                        status: room.status,
                        assigned_housekeeper_id: newId,
                      }),
                    });
                  }}
                />
              </td>
              <td>
                <button onClick={() => {
                  if (window.confirm(`Are you sure you want to delete room ${room.room_number}?`)) {
                    fetch(`/api/housekeeping-api/rooms/${room.id}`, {
                      method: 'DELETE',
                    }).then(() => {
                      setRooms(rooms.filter(r => r.id !== room.id));
                    });
                  }
                }}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Channel {
  id: string;
  name: string;
  adminUserId: string;
}

interface Message {
  id: string;
  text: string;
  channelId: string;
  authorId: string;
  timestamp: string;
}

export function ChatInterface() {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedChannelId, setSelectedChannelId] = useState<string | null>(null);
  const [newChannelName, setNewChannelName] = useState('');
  const [newMessageContent, setNewMessageContent] = useState('');
  const [currentUser] = useState({ id: 'user123', name: 'Current User' }); // Mock user

  // Fetch channels on component mount
  useEffect(() => {
    fetch('/api/channels-api/channels')
      .then(res => res.json())
      .then(data => setChannels(data));
  }, []);

  // Fetch messages when channel changes
  useEffect(() => {
    if (selectedChannelId) {
      fetch(`/api/channels-api/messages/channel/${selectedChannelId}`)
        .then(res => res.json())
        .then(data => setMessages(data));
    }
  }, [selectedChannelId]);

  const handleCreateChannel = () => {
    if (!newChannelName.trim()) return;

    fetch('/api/channels-api/channels', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: newChannelName,
        adminUserId: currentUser.id
      })
    })
    .then(res => res.json())
    .then(newChannel => {
      setChannels([...channels, newChannel]);
      setNewChannelName('');
    });
  };

  const handleSendMessage = () => {
    if (!newMessageContent.trim() || !selectedChannelId) return;

    const messageData = {
      text: newMessageContent,
      channelId: selectedChannelId,
      authorId: currentUser.id,
      timestamp: new Date().toISOString()
    };

    fetch('/api/channels-api/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(messageData)
    })
    .then(res => res.json())
    .then(newMessage => {
      setMessages([...messages, newMessage]);
      setNewMessageContent('');
    });
  };

  const handleSelectChannel = (channelId: string) => {
    setSelectedChannelId(channelId);
  };

  return (
    <div className="chat-interface">
      <h1>Team Chat</h1>

      <div className="channels-section">
        <h2>Channels</h2>
        <ul>
          {channels.map(channel => (
            <li key={channel.id}>
              <button onClick={() => handleSelectChannel(channel.id)}>
                {channel.name}
              </button>
            </li>
          ))}
        </ul>

        <div className="create-channel">
          <input
            type="text"
            placeholder="New channel name"
            value={newChannelName}
            onChange={(e) => setNewChannelName(e.target.value)}
          />
          <button onClick={handleCreateChannel}>Create Channel</button>
        </div>
      </div>

      <div className="messages-section">
        <h2>{selectedChannelId ? `Messages in Channel` : 'Select a Channel'}</h2>

        {selectedChannelId && (
          <>
            <div className="messages-list">
              {messages.map(message => (
                <div key={message.id} className="message">
                  <strong>{message.authorId}</strong>: {message.text}
                </div>
              ))}
            </div>

            <div className="send-message">
              <input
                type="text"
                placeholder="Type your message..."
                value={newMessageContent}
                onChange={(e) => setNewMessageContent(e.target.value)}
              />
              <button onClick={handleSendMessage}>Send</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

