import { useState, useEffect } from 'react';

interface ShortUrl {
  id: string;
  shortCode: string;
  targetUrl: string;
  visitCount: number;
}

export function ShortenerWebClient() {
  const [originalUrl, setOriginalUrl] = useState('');
  const [shortCode, setShortCode] = useState('');
  const [shortUrls, setShortUrls] = useState<ShortUrl[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShortUrls();
  }, []);

  const fetchShortUrls = async () => {
    try {
      const response = await fetch('/api/shortener-api/short-urls');
      if (!response.ok) throw new Error('Failed to fetch short URLs');
      const data = await response.json();
      setShortUrls(data);
    } catch (err) {
      setError('Error loading short URLs');
      console.error(err);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!originalUrl || !shortCode) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/shortener-api/short-urls', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          shortCode,
          targetUrl: originalUrl
        })
      });

      if (!response.ok) throw new Error('Failed to create short URL');

      await fetchShortUrls(); // Refresh the list
      setOriginalUrl('');
      setShortCode('');
    } catch (err) {
      setError('Error creating short URL');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleVisit = async (id: string) => {
    try {
      await fetch(`/api/shortener-api/short-urls/${id}/visit`, {
        method: 'PUT'
      });
      await fetchShortUrls(); // Refresh the list
    } catch (err) {
      console.error('Error tracking visit:', err);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await fetch(`/api/shortener-api/short-urls/${id}`, {
        method: 'DELETE'
      });
      await fetchShortUrls(); // Refresh the list
    } catch (err) {
      console.error('Error deleting short URL:', err);
    }
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">URL Shortener</h1>

      <form onSubmit={handleSubmit} className="mb-6 p-4 bg-gray-100 rounded">
        <div className="mb-3">
          <label htmlFor="originalUrl" className="block text-sm font-medium mb-1">
            Original URL
          </label>
          <input
            type="url"
            id="originalUrl"
            value={originalUrl}
            onChange={(e) => setOriginalUrl(e.target.value)}
            className="w-full p-2 border rounded"
            placeholder="https://example.com"
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="shortCode" className="block text-sm font-medium mb-1">
            Short Code
          </label>
          <input
            type="text"
            id="shortCode"
            value={shortCode}
            onChange={(e) => setShortCode(e.target.value)}
            className="w-full p-2 border rounded"
            placeholder="my-short-code"
            required
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 disabled:opacity-50"
        >
          {loading ? 'Creating...' : 'Create Short URL'}
        </button>

        {error && <p className="mt-2 text-red-500">{error}</p>}
      </form>

      <h2 className="text-xl font-semibold mb-3">Your Short URLs</h2>

      {shortUrls.length === 0 ? (
        <p className="text-gray-500">No short URLs created yet.</p>
      ) : (
        <div className="space-y-3">
          {shortUrls.map((url) => (
            <div key={url.id} className="p-3 border rounded flex justify-between items-center">
              <div>
                <div className="font-mono text-blue-600">
                  <a href={`/api/shortener-api/short-urls/${url.shortCode}`} target="_blank" rel="noopener noreferrer">
                    /{url.shortCode}
                  </a>
                </div>
                <div className="text-sm text-gray-600 truncate max-w-xs">
                  {url.targetUrl}
                </div>
                <div className="text-xs text-gray-500 mt-1">
                  Visits: {url.visitCount}
                </div>
              </div>
              <div className="flex space-x-2">
                <button
                  onClick={() => handleVisit(url.id)}
                  className="px-2 py-1 text-xs bg-green-500 text-white rounded hover:bg-green-600"
                >
                  Track Visit
                </button>
                <button
                  onClick={() => handleDelete(url.id)}
                  className="px-2 py-1 text-xs bg-red-500 text-white rounded hover:bg-red-600"
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';

interface BoxContent {
  memberId: number;
  weekDate: string;
  contents: string;
}

export function StaffLockScreen() {
  const [boxContents, setBoxContents] = useState<BoxContent[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/box-api/')
      .then(response => response.json())
      .then(data => {
        setBoxContents(data);
        setLoading(false);
      });
  }, []);

  const handleFinalize = (memberId: number, weekDate: string) => {
    // Finalize the box content by sending a PUT request with required fields
    fetch(`/api/box-api/${memberId}/${weekDate}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        contents: boxContents.find(item => 
          item.memberId === memberId && item.weekDate === weekDate
        )?.contents || '',
      }),
    });
  };

  const handleContentChange = (memberId: number, weekDate: string, content: string) => {
    setBoxContents(prev => 
      prev.map(item => 
        item.memberId === memberId && item.weekDate === weekDate 
          ? { ...item, contents: content } 
          : item
      )
    );
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>Staff Lock Screen</h1>
      <p>Finalize the week's box contents</p>

      {boxContents.map(({ memberId, weekDate, contents }) => (
        <div key={`${memberId}-${weekDate}`}>
          <label>
            Member ID: {memberId} - Week: {weekDate}
            <textarea
              value={contents}
              onChange={(e) => handleContentChange(memberId, weekDate, e.target.value)}
              rows={4}
              cols={50}
            />
          </label>
          <button onClick={() => handleFinalize(memberId, weekDate)}>Finalize</button>
        </div>
      ))}
    </div>
  );
}

import { useState, useEffect } from 'react';

interface StopData {
  id: number;
  tripId: number;
  stopNumber: number;
  location: string;
  note: string;
}

export function StopNoteEditor() {
  const [stops, setStops] = useState<StopData[]>([]);
  const [selectedStopId, setSelectedStopId] = useState<number | null>(null);
  const [location, setLocation] = useState('');
  const [note, setNote] = useState('');

  useEffect(() => {
    fetch('/api/trip-api/stops')
      .then(response => response.json())
      .then(data => setStops(data));
  }, []);

  const handleSelectStop = (id: number) => {
    const stop = stops.find(s => s.id === id);
    if (stop) {
      setSelectedStopId(id);
      setLocation(stop.location);
      setNote(stop.note);
    }
  };

  const handleSave = () => {
    if (selectedStopId === null) return;

    fetch(`/api/trip-api/stops/${selectedStopId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        tripId: stops.find(s => s.id === selectedStopId)?.tripId || 0,
        stopNumber: stops.find(s => s.id === selectedStopId)?.stopNumber || 0,
        location,
        note,
      }),
    });
  };

  const handleAddNew = () => {
    fetch('/api/trip-api/stops', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        tripId: 1,
        stopNumber: stops.length + 1,
        location: '',
        note: '',
      }),
    })
      .then(response => response.json())
      .then(newStop => {
        setStops([...stops, newStop]);
        setSelectedStopId(newStop.id);
        setLocation('');
        setNote('');
      });
  };

  return (
    <div>
      <h2>Stop Note Editor</h2>
      <div>
        <label>
          Location:
          <input
            type="text"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
        </label>
      </div>
      <div>
        <label>
          Note:
          <textarea
            value={note}
            onChange={(e) => setNote(e.target.value)}
          />
        </label>
      </div>
      <button onClick={handleSave} disabled={selectedStopId === null}>Save</button>
      <button onClick={handleAddNew}>Add New Stop</button>
      <div>
        <h3>Existing Stops:</h3>
        <ul>
          {stops.map(stop => (
            <li key={stop.id}>
              <span>{stop.location}</span>
              <button onClick={() => handleSelectStop(stop.id)}>Edit</button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

