import { useState } from 'react';

export function MachineReportForm() {
  const [machineId, setMachineId] = useState('');
  const [memberId, setMemberId] = useState('');
  const [reportText, setReportText] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const response = await fetch('/api/machine-reports-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          memberId,
          machineId,
          reportText,
        }),
      });

      if (response.ok) {
        setSubmitSuccess(true);
        // Reset form
        setMachineId('');
        setMemberId('');
        setReportText('');
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="machine-report-form">
      <h2>Report Broken Machine</h2>

      {submitSuccess ? (
        <div className="success-message">
          <p>Report submitted successfully!</p>
        </div>
      ) : (
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="memberId">Member ID:</label>
            <input
              id="memberId"
              type="text"
              value={memberId}
              onChange={(e) => setMemberId(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="machineId">Machine ID:</label>
            <input
              id="machineId"
              type="text"
              value={machineId}
              onChange={(e) => setMachineId(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="reportText">Description:</label>
            <textarea
              id="reportText"
              value={reportText}
              onChange={(e) => setReportText(e.target.value)}
              required
            />
          </div>

          <button type="submit" disabled={isSubmitting}>
            {isSubmitting ? 'Submitting...' : 'Submit Report'}
          </button>
        </form>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Repository {
  id: number;
  name: string;
  description: string;
  owner_id: number;
}

export function RepositoryDashboard() {
  const [repositories, setRepositories] = useState<Repository[]>([]);
  const [newRepoName, setNewRepoName] = useState('');
  const [newRepoDescription, setNewRepoDescription] = useState('');
  const [newRepoOwnerId, setNewRepoOwnerId] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/git-hosting-service/repositories')
      .then(res => res.json())
      .then(data => {
        setRepositories(data);
        setLoading(false);
      });
  }, []);

  const handleCreateRepo = () => {
    if (!newRepoName || !newRepoOwnerId) return;

    fetch('/api/git-hosting-service/repositories', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: newRepoName,
        description: newRepoDescription,
        owner_id: Number(newRepoOwnerId)
      })
    })
    .then(res => res.json())
    .then(repo => {
      setRepositories([...repositories, repo]);
      setNewRepoName('');
      setNewRepoDescription('');
      setNewRepoOwnerId('');
    });
  };

  const handleDeleteRepo = (id: number) => {
    fetch(`/api/git-hosting-service/repositories/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setRepositories(repositories.filter(repo => repo.id !== id));
    });
  };

  if (loading) {
    return <div>Loading repositories...</div>;
  }

  return (
    <div>
      <h1>Repository Dashboard</h1>

      <div>
        <h2>Create New Repository</h2>
        <input
          type="text"
          placeholder="Repository Name"
          value={newRepoName}
          onChange={(e) => setNewRepoName(e.target.value)}
        />
        <input
          type="text"
          placeholder="Owner ID"
          value={newRepoOwnerId}
          onChange={(e) => setNewRepoOwnerId(e.target.value)}
        />
        <textarea
          placeholder="Description"
          value={newRepoDescription}
          onChange={(e) => setNewRepoDescription(e.target.value)}
        />
        <button onClick={handleCreateRepo}>Create Repository</button>
      </div>

      <div>
        <h2>Repositories</h2>
        <ul>
          {repositories.map(repo => (
            <li key={repo.id}>
              <span>{repo.name} - {repo.description}</span>
              <button onClick={() => handleDeleteRepo(repo.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Machine {
  id: number;
  name: string;
  status: 'operational' | 'broken';
  lastBrokenTimestamp?: string;
}

export function MaintenancePanel() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [selectedMachineId, setSelectedMachineId] = useState<number | null>(null);

  useEffect(() => {
    fetch('/api/machine-tracker-api/machines')
      .then(res => res.json())
      .then(data => setMachines(data));
  }, []);

  const handleMarkFixed = () => {
    if (selectedMachineId === null) return;

    const machine = machines.find(m => m.id === selectedMachineId);
    if (!machine) return;

    // Update the machine status to operational
    fetch(`/api/machine-tracker-api/machines/${selectedMachineId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        status: 'operational',
        lastBrokenTimestamp: machine.lastBrokenTimestamp,
      }),
    })
    .then(res => res.json())
    .then(updatedMachine => {
      setMachines(machines.map(m => 
        m.id === updatedMachine.id ? updatedMachine : m
      ));
      setSelectedMachineId(null);
    });
  };

  return (
    <div>
      <h1>Maintenance Panel</h1>
      <p>Select a machine to mark as fixed:</p>

      <select 
        value={selectedMachineId ?? ''}
        onChange={(e) => setSelectedMachineId(e.target.value ? Number(e.target.value) : null)}
      >
        <option value="">-- Select Machine --</option>
        {machines
          .filter(machine => machine.status === 'broken')
          .map(machine => (
            <option key={machine.id} value={machine.id}>{machine.name}</option>
          ))}
      </select>

      <button 
        onClick={handleMarkFixed}
        disabled={selectedMachineId === null}
      >
        Mark as Fixed
      </button>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface InvoiceData {
  id?: number;
  clientId: string;
  title: string;
  description: string;
  amount: number;
  status: string;
  dueDate: string;
}

export function InvoiceEditor() {
  const [invoice, setInvoice] = useState<InvoiceData>({
    clientId: '',
    title: '',
    description: '',
    amount: 0,
    status: 'draft',
    dueDate: new Date().toISOString().split('T')[0],
  });

  const [invoices, setInvoices] = useState<InvoiceData[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchInvoices();
  }, []);

  const fetchInvoices = async () => {
    try {
      const response = await fetch('/api/billing-api/');
      const data = await response.json();
      setInvoices(data);
      setLoading(false);
    } catch (error) {
      console.error('Failed to fetch invoices:', error);
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setInvoice({
      ...invoice,
      [name]: name === 'amount' ? Number(value) : value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      if (editingId !== null) {
        // Update existing invoice
        const response = await fetch(`/api/billing-api/${editingId}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(invoice),
        });

        if (!response.ok) {
          throw new Error(`Failed to update invoice: ${response.status}`);
        }

        // Refresh the list
        fetchInvoices();
        setEditingId(null);
      } else {
        // Create new invoice
        const response = await fetch('/api/billing-api/', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(invoice),
        });

        if (!response.ok) {
          throw new Error(`Failed to create invoice: ${response.status}`);
        }

        // Refresh the list
        fetchInvoices();
      }

      // Reset form
      setInvoice({
        clientId: '',
        title: '',
        description: '',
        amount: 0,
        status: 'draft',
        dueDate: new Date().toISOString().split('T')[0],
      });
    } catch (error) {
      console.error('Error submitting invoice:', error);
    }
  };

  const handleEdit = (invoiceToEdit: InvoiceData) => {
    setInvoice(invoiceToEdit);
    setEditingId(invoiceToEdit.id!);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/billing-api/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete invoice: ${response.status}`);
      }

      // Refresh the list
      fetchInvoices();
    } catch (error) {
      console.error('Error deleting invoice:', error);
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="invoice-editor">
      <h2>{editingId ? 'Edit Invoice' : 'Create New Invoice'}</h2>

      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="clientId">Client ID:</label>
          <input
            type="text"
            id="clientId"
            name="clientId"
            value={invoice.clientId}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label htmlFor="title">Title:</label>
          <input
            type="text"
            id="title"
            name="title"
            value={invoice.title}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label htmlFor="description">Description:</label>
          <textarea
            id="description"
            name="description"
            value={invoice.description}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label htmlFor="amount">Amount:</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={invoice.amount}
            onChange={handleInputChange}
            required
          />
        </div>

