import { useState, useEffect } from 'react';

interface AirtimeSlot {
  id: number;
  showId: number;
  timestamp: string;
  claimedBy: string | null;
}

interface Show {
  id: number;
  title: string;
}

export function AirtimeSlotClaimUi() {
  const [slots, setSlots] = useState<AirtimeSlot[]>([]);
  const [shows, setShows] = useState<Show[]>([]);
  const [selectedSlotId, setSelectedSlotId] = useState<number | null>(null);
  const [djName, setDjName] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch('/api/scheduling-api/')
      .then(res => res.json())
      .then(data => {
        setSlots(data);
        setLoading(false);
      })
      .catch(err => {
        setError('Failed to load airtime slots');
        setLoading(false);
      });

    fetch('/api/scheduling-api/')
      .then(res => res.json())
      .then(data => {
        // Extract unique shows from slots
        const uniqueShows = Array.from(
          new Set(data.map((slot: AirtimeSlot) => slot.showId))
        ).map(id => ({ id, title: `Show ${id}` }));
        setShows(uniqueShows);
      })
      .catch(err => {
        setError('Failed to load shows');
      });
  }, []);

  const handleClaimSlot = () => {
    if (selectedSlotId === null || !djName.trim()) {
      setError('Please select a slot and enter your name');
      return;
    }

    const slotToClaim = slots.find(slot => slot.id === selectedSlotId);
    if (!slotToClaim) {
      setError('Selected slot not found');
      return;
    }

    // Make PUT request to update the slot with required fields
    fetch(`/api/scheduling-api/${selectedSlotId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        djId: djName,
        showId: slotToClaim.showId,
        timestamp: slotToClaim.timestamp,
      }),
    })
      .then(res => {
        if (!res.ok) {
          throw new Error('Failed to claim slot');
        }
        return res.json();
      })
      .then(updatedSlot => {
        setSlots(slots.map(slot => 
          slot.id === selectedSlotId ? updatedSlot : slot
        ));
        setSelectedSlotId(null);
        setDjName('');
        setError(null);
      })
      .catch(err => {
        setError('Failed to claim slot: ' + err.message);
      });
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div>
      <h1>Airtime Slot Claim</h1>
      <p>Select an unclaimed slot and enter your name to claim it.</p>

      {error && <div style={{ color: 'red' }}>{error}</div>}

      <div>
        <h2>Available Slots</h2>
        <ul>
          {slots
            .filter(slot => slot.claimedBy === null)
            .map(slot => (
              <li key={slot.id}>
                <span>{new Date(slot.timestamp).toLocaleString()} - Show {slot.showId}</span>
                <button 
                  onClick={() => {
                    setSelectedSlotId(slot.id);
                    setDjName('');
                  }}
                  disabled={selectedSlotId === slot.id}
                >
                  {selectedSlotId === slot.id ? 'Selected' : 'Select'}
                </button>
              </li>
            ))}
        </ul>
      </div>

      {selectedSlotId !== null && (
        <div>
          <h2>Claim Slot</h2>
          <p>Slot ID: {selectedSlotId}</p>
          <label>
            Your Name:
            <input 
              type="text" 
              value={djName}
              onChange={(e) => setDjName(e.target.value)}
            />
          </label>
          <button onClick={handleClaimSlot}>Claim Slot</button>
        </div>
      )}
    </div>
  );
}

