    if (!shift) return;

    try {
      const response = await fetch(`/api/shifts-api/${shift.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          parentId,
          shiftDate: shift.shiftDate,
          role: shift.role,
          caregiver,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update shift');
      }

      alert('Successfully signed up for shift!');
    } catch (err) {
      setError('Error signing up for shift');
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!shift) return <div>No shift found</div>;

  return (
    <div>
      <h2>Sign Up for Shift</h2>
      <p>Date: {shift.shiftDate}</p>
      <p>Role: {shift.role}</p>

      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="parentId">Parent ID:</label>
          <input
            id="parentId"
            type="text"
            value={parentId}
            onChange={(e) => setParentId(e.target.value)}
            required
          />
        </div>

        <div>
          <label htmlFor="caregiver">Caregiver Name:</label>
          <input
            id="caregiver"
            type="text"
            value={caregiver}
            onChange={(e) => setCaregiver(e.target.value)}
            required
          />
        </div>

        <button type="submit">Sign Up</button>
      </form>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface SessionData {
  id: string;
  title: string;
  participants: string[];
  screenShared: boolean;
  reactions: { [key: string]: number };
  polls: { id: string; question: string; options: string[]; votes: { [option: string]: number } }[];
}

export function MeetingRoomUi() {
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [newPollQuestion, setNewPollQuestion] = useState('');
  const [newPollOptions, setNewPollOptions] = useState('');
  const [chatMessage, setChatMessage] = useState('');
  const [reaction, setReaction] = useState('');

  // Create a new session
  const createSession = async () => {
    try {
      const response = await fetch('/api/conferencing-server/create-session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: 'My Meeting' }),
      });
      const data = await response.json();
      setSessionId(data.id);
    } catch (error) {
      console.error('Failed to create session:', error);
    }
  };

  // Fetch session data
  useEffect(() => {
    if (!sessionId) return;

    const fetchSession = async () => {
      try {
        const response = await fetch(`/api/conferencing-server/session/${sessionId}`);
        const data = await response.json();
        setSessionData(data);
      } catch (error) {
        console.error('Failed to fetch session:', error);
      }
    };

    fetchSession();
  }, [sessionId]);

  // Update session data
  const updateSession = async (updates: Partial<SessionData>) => {
    if (!sessionId) return;

    try {
      await fetch(`/api/conferencing-server/session/${sessionId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updates),
      });

      // Refresh data after update
      const response = await fetch(`/api/conferencing-server/session/${sessionId}`);
      const data = await response.json();
      setSessionData(data);
    } catch (error) {
      console.error('Failed to update session:', error);
    }
  };

  // Add a reaction
  const addReaction = () => {
    if (!reaction || !sessionId) return;

    updateSession({
      reactions: {
        ...sessionData?.reactions,
        [reaction]: (sessionData?.reactions[reaction] || 0) + 1
      }
    });
    setReaction('');
  };

  // Start screen sharing
  const toggleScreenShare = () => {
    if (!sessionId) return;

    updateSession({
      screenShared: !sessionData?.screenShared
    });
  };

  // Create a poll
  const createPoll = () => {
    if (!newPollQuestion || !newPollOptions || !sessionId) return;

    const options = newPollOptions.split(',').map(opt => opt.trim());

    updateSession({
      polls: [
        ...(sessionData?.polls || []),
        {
          id: Date.now().toString(),
          question: newPollQuestion,
          options,
          votes: {}
        }
      ]
    });

    setNewPollQuestion('');
    setNewPollOptions('');
  };

  // Send a chat message
  const sendChatMessage = () => {
    if (!chatMessage || !sessionId) return;

    // In a real app, we'd send the message to a backend service
    // For now, just log it
    console.log(`Sending chat message: ${chatMessage}`);
    setChatMessage('');
  };

  return (
    <div className="meeting-room">
      <h1>Meeting Room</h1>

      {!sessionId ? (
        <button onClick={createSession}>Start New Meeting</button>
      ) : (
        <>
          <p>Session ID: {sessionId}</p>

          <div className="controls">
            <button onClick={toggleScreenShare}>
              {sessionData?.screenShared ? 'Stop Sharing' : 'Share Screen'}
            </button>

            <div className="reactions">
              <input 
                type="text" 
                placeholder="Add reaction (e.g., thumbs-up)"
                value={reaction}
                onChange={(e) => setReaction(e.target.value)}
              />
              <button onClick={addReaction}>Send Reaction</button>
            </div>

            <div className="poll">
              <input 
                type="text" 
                placeholder="Poll question"
                value={newPollQuestion}
                onChange={(e) => setNewPollQuestion(e.target.value)}
              />
              <input 
                type="text" 
                placeholder="Options separated by commas"
                value={newPollOptions}
                onChange={(e) => setNewPollOptions(e.target.value)}
              />
              <button onClick={createPoll}>Create Poll</button>
            </div>

            <div className="chat">
              <input 
                type="text" 
                placeholder="Type a message..."
                value={chatMessage}
                onChange={(e) => setChatMessage(e.target.value)}
              />
              <button onClick={sendChatMessage}>Send Message</button>
            </div>
          </div>

          <div className="session-info">
            <h2>Session Details</h2>
            <p>Title: {sessionData?.title || 'Untitled'}</p>
            <p>Participants: {sessionData?.participants?.length || 0}</p>
            <p>Screen Shared: {sessionData?.screenShared ? 'Yes' : 'No'}</p>
            <p>Reactions: {Object.entries(sessionData?.reactions || {}).map(([key, value]) => `${key}: ${value}`).join(', ') || 'None'}</p>
            <p>Polls: {sessionData?.polls?.length || 0} active</p>
          </div>
        </>
      )}
    </div>
  );
}

