import { useState, useEffect } from 'react';

interface Desk {
  id: number;
  name: string;
}

interface Booking {
  id: number;
  member_id: number;
  desk_id: number;
  date: string;
  status: string;
}

export function DeskBookingCalendar() {
  const [desks, setDesks] = useState<Desk[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedDeskId, setSelectedDeskId] = useState<number | null>(null);
  const [memberId, setMemberId] = useState<number>(0);

  useEffect(() => {
    // Fetch desks
    fetch('/api/bookings-api/')
      .then(response => response.json())
      .then(data => setDesks(data));

    // Fetch bookings
    fetch('/api/bookings-api/')
      .then(response => response.json())
      .then(data => setBookings(data));
  }, []);

  const handleBookDesk = () => {
    if (selectedDate && selectedDeskId && memberId) {
      fetch('/api/bookings-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          member_id: memberId,
          desk_id: selectedDeskId,
          date: selectedDate,
          status: 'confirmed',
        }),
      })
        .then(response => response.json())
        .then(newBooking => {
          setBookings([...bookings, newBooking]);
          setSelectedDeskId(null);
        });
    }
  };

  const availableDesks = desks.filter(desk => {
    return !bookings.some(booking => 
      booking.desk_id === desk.id && 
      booking.date === selectedDate
    );
  });

  return (
    <div>
      <h1>Desk Booking Calendar</h1>

      <div>
        <label htmlFor="memberId">Member ID:</label>
        <input
          id="memberId"
          type="number"
          value={memberId}
          onChange={(e) => setMemberId(Number(e.target.value))}
        />
      </div>

      <div>
        <label htmlFor="date">Select Date:</label>
        <input
          id="date"
          type="date"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
        />
      </div>

      <div>
        <h2>Available Desks</h2>
        <ul>
          {availableDesks.map(desk => (
            <li key={desk.id}>
              <span>{desk.name}</span>
              <button 
                onClick={() => setSelectedDeskId(desk.id)} 
                disabled={selectedDeskId === desk.id}
              >
                {selectedDeskId === desk.id ? 'Selected' : 'Select'}
              </button>
            </li>
          ))}
        </ul>
      </div>

      <button 
        onClick={handleBookDesk} 
        disabled={!selectedDate || !selectedDeskId || !memberId}
      >
        Book Selected Desk
      </button>
    </div>
  );
}

