      body: JSON.stringify(formData),
    })
      .then(res => res.json())
      .then(newTour => {
        setTours([...tours, newTour]);
        setFormData({ docentId: 0, exhibitId: 0, date: '' });
      })
      .catch(err => {
        setError('Failed to book tour');
      });
  };

  if (loading) return <div>Loading tours...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div>
      <h2>Book a Tour</h2>
