        <div>
          <label htmlFor="exhibitId">Exhibit ID:</label>
          <input
            type="number"
            id="exhibitId"
            name="exhibitId"
            value={formData.exhibitId}
            onChange={handleInputChange}
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleInputChange}
            required
          />
        </div>
        <button type="submit">Book Tour</button>
      </form>

      <h3>Available Tours</h3>
      <ul>
        {tours.map(tour => (
