import { useEffect, useState } from 'react';

interface TimesheetEntry {
  id: number;
  associateId: number;
  date: string;
  rate: number;
  description: string;
}

export function MemberDashboard() {
  const [entries, setEntries] = useState<TimesheetEntry[]>([]);
  const [newEntry, setNewEntry] = useState({
    associateId: 0,
    date: '',
    rate: 0,
    description: ''
  });

  useEffect(() => {
    fetch('/api/timesheets-api/')
      .then(res => res.json())
      .then(data => setEntries(data));
  }, []);

  const handleAddEntry = () => {
    fetch('/api/timesheets-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newEntry)
    })
    .then(res => res.json())
    .then(data => {
      setEntries([...entries, data]);
      setNewEntry({
        associateId: 0,
        date: '',
        rate: 0,
        description: ''
      });
    });
  };

  const handleDeleteEntry = (id: number) => {
    fetch(`/api/timesheets-api/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setEntries(entries.filter(entry => entry.id !== id));
    });
  };

  return (
    <div>
      <h1>My Timesheet Entries</h1>
      <table>
        <thead>
          <tr>
            <th>Date</th>
            <th>Rate</th>
            <th>Description</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {entries.map(entry => (
            <tr key={entry.id}>
              <td>{entry.date}</td>
              <td>{entry.rate}</td>
              <td>{entry.description}</td>
              <td>
                <button onClick={() => handleDeleteEntry(entry.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2>Add New Entry</h2>
      <div>
        <input
          type="number"
          placeholder="Associate ID"
          value={newEntry.associateId}
          onChange={(e) => setNewEntry({...newEntry, associateId: Number(e.target.value)})}
        />
        <input
          type="date"
          placeholder="Date"
          value={newEntry.date}
          onChange={(e) => setNewEntry({...newEntry, date: e.target.value})}
        />
        <input
          type="number"
          placeholder="Rate"
          value={newEntry.rate}
          onChange={(e) => setNewEntry({...newEntry, rate: Number(e.target.value)})}
        />
        <input
          type="text"
          placeholder="Description"
          value={newEntry.description}
          onChange={(e) => setNewEntry({...newEntry, description: e.target.value})}
        />
        <button onClick={handleAddEntry}>Add Entry</button>
      </div>
    </div>
  );
}

