import { useState, useEffect } from 'react';

interface ClassSchedule {
  id: number;
  name: string;
  schedule: string;
  maxEnrollment: number;
  enrolledMembers: number;
}

export function ClassScheduling() {
  const [classes, setClasses] = useState<ClassSchedule[]>([]);
  const [selectedClassId, setSelectedClassId] = useState<number | null>(null);
  const [memberId, setMemberId] = useState<string>('');

  useEffect(() => {
    // Simulate fetching class schedules
    const mockClasses: ClassSchedule[] = [
      { id: 1, name: 'Yoga', schedule: 'Mon, Wed, Fri 6:00 AM', maxEnrollment: 15, enrolledMembers: 12 },
      { id: 2, name: 'Spinning', schedule: 'Tue, Thu 7:00 PM', maxEnrollment: 20, enrolledMembers: 18 },
      { id: 3, name: 'Zumba', schedule: 'Sat 9:00 AM', maxEnrollment: 25, enrolledMembers: 20 },
    ];
    setClasses(mockClasses);
  }, []);

  const handleRegister = async (classId: number) => {
    try {
      const response = await fetch(`/api/class-service/classes/${classId}/enroll`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ memberId }),
      });

      if (!response.ok) {
        throw new Error('Failed to register for class');
      }

      // Update UI after successful registration
      setClasses(prevClasses => 
        prevClasses.map(cls => 
          cls.id === classId 
            ? { ...cls, enrolledMembers: cls.enrolledMembers + 1 } 
            : cls
        )
      );

      setSelectedClassId(null);
    } catch (error) {
      console.error('Registration failed:', error);
    }
  };

  return (
    <div className="class-scheduling-page">
      <h1>Fitness Class Schedules</h1>

      <div className="class-list">
        {classes.map(cls => (
          <div key={cls.id} className="class-card">
            <h2>{cls.name}</h2>
            <p>Schedule: {cls.schedule}</p>
            <p>Enrollment: {cls.enrolledMembers}/{cls.maxEnrollment}</p>

            {selectedClassId === cls.id ? (
              <div className="registration-form">
                <input
                  type="text"
                  placeholder="Enter Member ID"
                  value={memberId}
                  onChange={(e) => setMemberId(e.target.value)}
                  className="member-id-input"
                />
                <button onClick={() => handleRegister(cls.id)}>Confirm Registration</button>
                <button onClick={() => setSelectedClassId(null)}>Cancel</button>
              </div>
            ) : (
              <button 
                onClick={() => setSelectedClassId(cls.id)}
                disabled={cls.enrolledMembers >= cls.maxEnrollment}
              >
                Register for Class
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

