import { useState, useEffect } from 'react';

interface Category {
  id: number;
  name: string;
  description: string;
}

export function CategoriesPage() {
  const [categories, setCategories] = useState<Category[]>([]);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await fetch('/api/categories-api/categories');
      const data = await response.json();
      setCategories(data);
    } catch (error) {
      console.error('Failed to fetch categories:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId !== null) {
      // Update existing category
      try {
        await fetch(`/api/categories-api/categories/${editingId}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ name, description }),
        });
        setEditingId(null);
      } catch (error) {
        console.error('Failed to update category:', error);
      }
    } else {
      // Create new category
      try {
        await fetch('/api/categories-api/categories', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ name, description }),
        });
      } catch (error) {
        console.error('Failed to create category:', error);
      }
    }

    // Reset form and refetch categories
    setName('');
    setDescription('');
    fetchCategories();
  };

  const handleEdit = (category: Category) => {
    setName(category.name);
    setDescription(category.description);
    setEditingId(category.id);
  };

  const handleDelete = async (id: number) => {
    try {
      await fetch(`/api/categories-api/categories/${id}`, {
        method: 'DELETE',
      });
      fetchCategories();
    } catch (error) {
      console.error('Failed to delete category:', error);
    }
  };

  return (
    <div>
      <h1>Manage Categories</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
        </div>
        <div>
          <label htmlFor="description">Description:</label>
          <input
            id="description"
            type="text"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            required
          />
        </div>
        <button type="submit">
          {editingId ? 'Update Category' : 'Add Category'}
        </button>
      </form>

      <h2>Existing Categories</h2>
      <ul>
        {categories.map((category) => (
          <li key={category.id}>
            <span>{category.name}: {category.description}</span>
            <button onClick={() => handleEdit(category)}>Edit</button>
            <button onClick={() => handleDelete(category.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Placement {
  id: number;
  company: string;
  position: string;
  salary: number;
  date: string;
}

export function PlacementRecords() {
  const [placements, setPlacements] = useState<Placement[]>([]);
  const [formData, setFormData] = useState<Omit<Placement, 'id'>>({ 
    company: '', 
    position: '', 
    salary: 0, 
    date: '' 
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchPlacements();
  }, []);

  const fetchPlacements = async () => {
    try {
      const response = await fetch('/api/placement-api/placements');
      const data = await response.json();
      setPlacements(data);
      setLoading(false);
    } catch (error) {
      console.error('Failed to fetch placements:', error);
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'salary' ? Number(value) : value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId !== null) {
      // Update existing placement
      const response = await fetch(`/api/placement-api/placements/${editingId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          company: formData.company,
          position: formData.position,
          salary: formData.salary,
          date: formData.date
        })
      });

      if (response.ok) {
        fetchPlacements();
        setEditingId(null);
      }
    } else {
      // Create new placement
      const response = await fetch('/api/placement-api/placements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          company: formData.company,
          position: formData.position,
          salary: formData.salary,
          date: formData.date
        })
      });

      if (response.ok) {
        fetchPlacements();
      }
    }

    // Reset form
    setFormData({ company: '', position: '', salary: 0, date: '' });
  };

  const handleEdit = (placement: Placement) => {
    setFormData({ 
      company: placement.company, 
      position: placement.position, 
      salary: placement.salary, 
      date: placement.date 
    });
    setEditingId(placement.id);
  };

  const handleDelete = async (id: number) => {
    const response = await fetch(`/api/placement-api/placements/${id}`, {
      method: 'DELETE'
    });

    if (response.ok) {
      fetchPlacements();
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>Placement Records</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="company"
          placeholder="Company"
          value={formData.company}
          onChange={handleInputChange}
          required
        />
        <input
          type="text"
          name="position"
          placeholder="Position"
          value={formData.position}
          onChange={handleInputChange}
          required
        />
        <input
          type="number"
          name="salary"
          placeholder="Salary"
          value={formData.salary}
          onChange={handleInputChange}
          required
        />
        <input
          type="date"
          name="date"
          value={formData.date}
          onChange={handleInputChange}
          required
        />
        <button type="submit">
          {editingId !== null ? 'Update Placement' : 'Add Placement'}
        </button>
      </form>

      <h2>Placement List</h2>
      <ul>
        {placements.map(placement => (
          <li key={placement.id}>
            <strong>{placement.company}</strong> - {placement.position} - ${placement.salary} - {placement.date}
            <button onClick={() => handleEdit(placement)}>Edit</button>
            <button onClick={() => handleDelete(placement.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

