          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          username: newUser.username,
          password: newUser.password,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to authenticate');
      }

      // In a real app, you'd handle the response and update state accordingly
      console.log('Login successful');
    } catch (error) {
      console.error('Login failed:', error);
    }
  };

  return (
    <div className="users-page">
      <h1>Staff Accounts</h1>

      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="username">Username:</label>
          <input
            type="text"
            id="username"
            name="username"
            value={newUser.username}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            name="password"
            value={newUser.password}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label htmlFor="role">Role:</label>
          <select
            id="role"
            name="role"
            value={newUser.role}
            onChange={handleInputChange}
          >
            <option value="staff">Staff</option>
            <option value="administrator">Administrator</option>
          </select>
        </div>

        <button type="submit">Add User</button>
      </form>

      <h2>Current Staff</h2>
      <ul>
        {users.map(user => (
          <li key={user.id}>
            {user.username} - {user.role}
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Task {
  id: number;
  description: string;
  status: 'pending' | 'in-progress' | 'completed';
  assignedTo: string;
  dueDate: string;
}

export function TaskListPage() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [filteredTasks, setFilteredTasks] = useState<Task[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'pending' | 'in-progress' | 'completed'>('all');

  useEffect(() => {
    // Simulate fetching tasks from API
    const mockTasks: Task[] = [
      {
        id: 1,
        description: 'Clean room 101',
        status: 'pending',
        assignedTo: 'John Doe',
        dueDate: '2023-06-15',
      },
      {
        id: 2,
        description: 'Restock supplies in lobby',
        status: 'in-progress',
        assignedTo: 'Jane Smith',
        dueDate: '2023-06-16',
      },
      {
        id: 3,
        description: 'Deep clean conference hall',
        status: 'completed',
        assignedTo: 'Bob Johnson',
        dueDate: '2023-06-14',
      },
    ];

    setTasks(mockTasks);
    setFilteredTasks(mockTasks);
  }, []);

  useEffect(() => {
    let result = tasks;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(task => 
        task.description.toLowerCase().includes(term) ||
        task.assignedTo.toLowerCase().includes(term)
      );
    }

    if (statusFilter !== 'all') {
      result = result.filter(task => task.status === statusFilter);
    }

    setFilteredTasks(result);
  }, [searchTerm, statusFilter, tasks]);

  const handleStatusChange = (taskId: number, newStatus: Task['status']) => {
    // Simulate updating task status via API
    fetch(`/api/task-management-service/tasks/${taskId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        description: tasks.find(t => t.id === taskId)?.description || '',
        status: newStatus,
        assignedTo: tasks.find(t => t.id === taskId)?.assignedTo || '',
        dueDate: tasks.find(t => t.id === taskId)?.dueDate || '',
      }),
    });

    setTasks(tasks.map(task => 
      task.id === taskId ? { ...task, status: newStatus } : task
    ));
  };

  return (
    <div className="task-list-page">
      <h1>Housekeeping Task Tracker</h1>

      <div className="filters">
        <input
          type="text"
          placeholder="Search tasks..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as any)}
          className="status-filter"
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="in-progress">In Progress</option>
          <option value="completed">Completed</option>
        </select>
      </div>

      <div className="task-list">
        {filteredTasks.length === 0 ? (
          <p>No tasks found.</p>
        ) : (
          filteredTasks.map(task => (
            <div key={task.id} className="task-item">
              <div className="task-info">
                <h3>{task.description}</h3>
                <p><strong>Assigned to:</strong> {task.assignedTo}</p>
                <p><strong>Due date:</strong> {task.dueDate}</p>
                <p><strong>Status:</strong> {task.status}</p>
              </div>

              <div className="task-actions">
                <select
                  value={task.status}
                  onChange={(e) => handleStatusChange(task.id, e.target.value as Task['status'])}
                >
                  <option value="pending">Pending</option>
                  <option value="in-progress">In Progress</option>
                  <option value="completed">Completed</option>
                </select>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

