import { useState, useEffect } from 'react';

interface TimeSlot {
  id: number;
  startTime: string;
  endTime: string;
  available: boolean;
}

export function SlotBookingPage() {
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedSlotId, setSelectedSlotId] = useState<number | null>(null);
  const [memberId, setMemberId] = useState<string>('');
  const [bookingStatus, setBookingStatus] = useState<string>('');

  useEffect(() => {
    // Fetch available time slots
    fetch('/api/slot-management-service')
      .then(response => response.json())
      .then(data => {
        setTimeSlots(data);
      })
      .catch(error => {
        console.error('Failed to fetch time slots:', error);
      });
  }, []);

  const handleSlotSelect = (slotId: number) => {
    setSelectedSlotId(slotId);
  };

  const handleBooking = () => {
    if (selectedSlotId === null || !memberId) {
      setBookingStatus('Please select a slot and enter your member ID');
      return;
    }

    // Book the selected slot using the correct API endpoint
    fetch('/api/booking-service/bookings', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        slotId: selectedSlotId,
        memberId: parseInt(memberId),
      }),
    })
      .then(response => {
        if (response.ok) {
          setBookingStatus('Booking successful!');
          // Refresh slots after booking
          fetch('/api/slot-management-service')
            .then(res => res.json())
            .then(data => {
              setTimeSlots(data);
            });
        } else {
          setBookingStatus('Booking failed. Please try again.');
        }
      })
      .catch(error => {
        console.error('Booking error:', error);
        setBookingStatus('Booking failed. Please try again.');
      });
  };

  return (
    <div className="slot-booking-page">
      <h1>Book a Time Slot</h1>

      <div className="member-id-input">
        <label htmlFor="memberId">Member ID:</label>
        <input
          type="text"
          id="memberId"
          value={memberId}
          onChange={(e) => setMemberId(e.target.value)}
          placeholder="Enter your member ID"
        />
      </div>

      <h2>Available Time Slots</h2>
      <div className="time-slots">
        {timeSlots.map((slot) => (
          <div
            key={slot.id}
            className={`slot ${selectedSlotId === slot.id ? 'selected' : ''} ${!slot.available ? 'unavailable' : ''}`}
            onClick={() => handleSlotSelect(slot.id)}
          >
            <span>{slot.startTime} - {slot.endTime}</span>
            {!slot.available && <span className="unavailable-text">(Unavailable)</span>}
          </div>
        ))}
      </div>

      <button onClick={handleBooking} disabled={selectedSlotId === null || !memberId}>
        Confirm Booking
      </button>

      {bookingStatus && <p className="booking-status">{bookingStatus}</p>}
    </div>
  );
}

