import { useState, useEffect } from 'react';

interface Car {
  id: number;
  make: string;
  model: string;
  year: number;
  color: string;
  dailyRate: number;
}

interface BookingForm {
  carId: number | null;
  startDate: string;
  endDate: string;
}

export function CarListPage() {
  const [cars, setCars] = useState<Car[]>([]);
  const [filteredCars, setFilteredCars] = useState<Car[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({
    make: '',
    model: '',
    minYear: '',
    maxYear: '',
    minDailyRate: '',
    maxDailyRate: ''
  });
  const [bookingForm, setBookingForm] = useState<BookingForm>({
    carId: null,
    startDate: '',
    endDate: ''
  });

  useEffect(() => {
    fetchCars();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [cars, filters]);

  const fetchCars = async () => {
    try {
      const response = await fetch('/api/car-management-api');
      if (!response.ok) {
        throw new Error('Failed to fetch cars');
      }
      const data = await response.json();
      setCars(data);
      setFilteredCars(data);
    } catch (err) {
      setError('Error fetching cars');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let result = [...cars];

    if (filters.make) {
      result = result.filter(car => 
        car.make.toLowerCase().includes(filters.make.toLowerCase())
      );
    }

    if (filters.model) {
      result = result.filter(car => 
        car.model.toLowerCase().includes(filters.model.toLowerCase())
      );
    }

    if (filters.minYear) {
      result = result.filter(car => car.year >= parseInt(filters.minYear));
    }

    if (filters.maxYear) {
      result = result.filter(car => car.year <= parseInt(filters.maxYear));
    }

    if (filters.minDailyRate) {
      result = result.filter(car => car.dailyRate >= parseFloat(filters.minDailyRate));
    }

    if (filters.maxDailyRate) {
      result = result.filter(car => car.dailyRate <= parseFloat(filters.maxDailyRate));
    }

    setFilteredCars(result);
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const handleBookingChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBookingForm(prev => ({ ...prev, [name]: value }));
  };

  const handleBookCar = async (carId: number) => {
    if (!bookingForm.startDate || !bookingForm.endDate) {
      alert('Please enter start and end dates');
      return;
    }

    try {
      const response = await fetch('/api/booking-management-api/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          carId,
          startDate: bookingForm.startDate,
          endDate: bookingForm.endDate
        })
      });

      if (!response.ok) {
        throw new Error('Failed to book car');
      }

      alert('Car booked successfully!');
      setBookingForm({ carId: null, startDate: '', endDate: '' });
    } catch (err) {
      setError('Error booking car');
      console.error(err);
    }
  };

  if (loading) return <div>Loading cars...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div className="car-list-page">
      <h1>Available Cars</h1>

      <div className="filters">
        <h2>Filter Cars</h2>
        <input
          type="text"
          name="make"
          placeholder="Make"
          value={filters.make}
          onChange={handleFilterChange}
        />
        <input
          type="text"
          name="model"
          placeholder="Model"
          value={filters.model}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="minYear"
          placeholder="Min Year"
          value={filters.minYear}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="maxYear"
          placeholder="Max Year"
          value={filters.maxYear}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="minDailyRate"
          placeholder="Min Daily Rate"
          value={filters.minDailyRate}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="maxDailyRate"
          placeholder="Max Daily Rate"
          value={filters.maxDailyRate}
          onChange={handleFilterChange}
        />
      </div>

      <div className="booking-form">
        <h2>Book a Car</h2>
        <input
          type="date"
          name="startDate"
          placeholder="Start Date"
          value={bookingForm.startDate}
          onChange={handleBookingChange}
        />
        <input
          type="date"
          name="endDate"
          placeholder="End Date"
          value={bookingForm.endDate}
          onChange={handleBookingChange}
        />
      </div>

      <div className="car-list">
        {filteredCars.length === 0 ? (
          <p>No cars found matching your criteria.</p>
        ) : (
          filteredCars.map(car => (
            <div key={car.id} className="car-card">
              <h3>{car.make} {car.model}</h3>
              <p>Year: {car.year}</p>
              <p>Color: {car.color}</p>
              <p>Daily Rate: ${car.dailyRate}</p>
              <button onClick={() => handleBookCar(car.id)}>Book Now</button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

