export function AppointmentScheduler() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [showForm, setShowForm] = useState<boolean>(false);

  // Form state
  const [formData, setFormData] = useState({
    patientId: '',
    date: selectedDate,
    time: '',
    service: ''
  });

  // Fetch appointments and patients
  useEffect(() => {
    fetch('/api/appointment-service/appointments')
      .then(res => res.json())
      .then(data => setAppointments(data));

    fetch('/api/patient-service/patients')
      .then(res => res.json())
      .then(data => setPatients(data));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    fetch('/api/appointment-service/appointments', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        patientId: Number(formData.patientId),
        date: formData.date,
        time: formData.time,
        service: formData.service
      })
    })
    .then(res => res.json())
    .then(newAppointment => {
      setAppointments(prev => [...prev, newAppointment]);
      setShowForm(false);
      setFormData({
        patientId: '',
        date: selectedDate,
        time: '',
        service: ''
      });
    });
  };

  const handleUpdate = (id: number, updatedFields: Partial<Appointment>) => {
    fetch(`/api/appointment-service/appointments/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        patientId: updatedFields.patientId || 0,
        date: updatedFields.date || '',
        time: updatedFields.time || '',
        service: updatedFields.service || ''
      })
    })
    .then(res => res.json())
    .then(updatedAppointment => {
      setAppointments(prev => 
        prev.map(app => app.id === id ? updatedAppointment : app)
      );
    });
  };

  const handleDelete = (id: number) => {
    fetch(`/api/appointment-service/appointments/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setAppointments(prev => prev.filter(app => app.id !== id));
    });
  };

  const getFilteredAppointments = () => {
    return appointments.filter(app => app.date === selectedDate);
  };

  return (
    <div className="appointment-scheduler">
      <h1>Dental Clinic Appointment Scheduler</h1>

      <div className="calendar-controls">
        <input 
          type="date" 
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
        />
        <button onClick={() => setShowForm(true)}>Add New Appointment</button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="appointment-form">
          <h2>Add New Appointment</h2>
          <select 
            name="patientId" 
            value={formData.patientId}
            onChange={handleInputChange}
            required
          >
            <option value="">Select Patient</option>
            {patients.map(patient => (
              <option key={patient.id} value={patient.id}>{patient.name}</option>
            ))}
          </select>

          <input 
            type="date" 
            name="date" 
            value={formData.date}
            onChange={handleInputChange}
            required
          />

          <input 
            type="time" 
            name="time" 
            value={formData.time}
            onChange={handleInputChange}
            required
          />

          <input 
            type="text" 
            name="service" 
            value={formData.service}
            onChange={handleInputChange}
            placeholder="Service"
            required
          />

          <button type="submit">Save Appointment</button>
          <button type="button" onClick={() => setShowForm(false)}>Cancel</button>
        </form>
      )}

      <div className="appointments-list">
        <h2>Appointments for {selectedDate}</h2>
        {getFilteredAppointments().length === 0 ? (
          <p>No appointments scheduled for this date.</p>
        ) : (
          <ul>
            {getFilteredAppointments().map(appointment => (
              <li key={appointment.id} className="appointment-item">
                <span>{appointment.time} - {appointment.service}</span>
                <div className="appointment-actions">
                  <button onClick={() => handleDelete(appointment.id)}>Delete</button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

