import { useState, useEffect } from 'react';

interface MenuItem {
  id: number;
  name: string;
  description: string;
  price: number;
}

interface OrderItem {
  menuItemId: number;
  quantity: number;
}

interface Order {
  id: number;
  status: string;
  items: OrderItem[];
  createdAt: string;
}

export function CustomerDashboard() {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedItems, setSelectedItems] = useState<{[key: number]: number}>({});
  const [customerId, setCustomerId] = useState<string>('');
  const [orderStatus, setOrderStatus] = useState<string>('');

  // Fetch menu items
  useEffect(() => {
    fetch('/api/menu')
      .then(res => res.json())
      .then(data => setMenuItems(data))
      .catch(err => console.error('Failed to fetch menu:', err));
  }, []);

  // Fetch customer orders
  useEffect(() => {
    if (customerId) {
      fetch(`/api/order-management-service/orders?customerId=${customerId}`)
        .then(res => res.json())
        .then(data => setOrders(data))
        .catch(err => console.error('Failed to fetch orders:', err));
    }
  }, [customerId]);

  const handleAddToOrder = (itemId: number) => {
    setSelectedItems(prev => ({
      ...prev,
      [itemId]: (prev[itemId] || 0) + 1
    }));
  };

  const handlePlaceOrder = () => {
    if (!customerId) {
      alert('Please enter your customer ID');
      return;
    }

    const orderItems: OrderItem[] = Object.entries(selectedItems)
      .filter(([_, quantity]) => quantity > 0)
      .map(([itemId, quantity]) => ({
        menuItemId: Number(itemId),
        quantity
      }));

    if (orderItems.length === 0) {
      alert('Please select at least one item');
      return;
    }

    fetch('/api/order-management-service/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        customerId,
        items: orderItems
      })
    })
    .then(res => res.json())
    .then(data => {
      setOrderStatus('Order placed successfully!');
      // Reset selection after placing order
      setSelectedItems({});
      // Refresh orders
      fetch(`/api/order-management-service/orders?customerId=${customerId}`)
        .then(res => res.json())
        .then(data => setOrders(data))
        .catch(err => console.error('Failed to fetch orders:', err));
    })
    .catch(err => {
      console.error('Failed to place order:', err);
      setOrderStatus('Failed to place order');
    });
  };

  return (
    <div className="customer-dashboard">
      <h1>Food Truck Order & Pickup</h1>

      <div className="customer-info">
        <label htmlFor="customerId">Customer ID:</label>
        <input
          id="customerId"
          type="text"
          value={customerId}
          onChange={(e) => setCustomerId(e.target.value)}
          placeholder="Enter your customer ID"
        />
      </div>

      <div className="menu-section">
        <h2>Menu</h2>
        <div className="menu-items">
          {menuItems.map(item => (
            <div key={item.id} className="menu-item">
              <h3>{item.name}</h3>
              <p>{item.description}</p>
              <p>${item.price.toFixed(2)}</p>
              <button onClick={() => handleAddToOrder(item.id)}>Add to Order</button>
            </div>
          ))}
        </div>
      </div>

      <div className="order-section">
        <h2>Your Order</h2>
        <div className="order-items">
          {Object.entries(selectedItems).length > 0 ? (
            Object.entries(selectedItems).map(([itemId, quantity]) => {
              const item = menuItems.find(i => i.id === Number(itemId));
              return item ? (
                <div key={itemId} className="order-item">
                  <span>{item.name} x{quantity}</span>
                </div>
              ) : null;
            })
          ) : (
            <p>No items selected</p>
          )}
        </div>
        <button onClick={handlePlaceOrder}>Place Order</button>
        {orderStatus && <p>{orderStatus}</p>}
      </div>

      <div className="orders-section">
        <h2>Your Orders</h2>
        <div className="orders-list">
          {orders.length > 0 ? (
            orders.map(order => (
              <div key={order.id} className="order">
                <p>Order #{order.id} - Status: {order.status}</p>
                <p>Created: {new Date(order.createdAt).toLocaleString()}</p>
              </div>
            ))
          ) : (
            <p>No orders found</p>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';

export function RecordFormPage() {
  const [formData, setFormData] = useState({
    title: '',
    date: '',
    agenda: '',
    meetingId: '',
    description: '',
    amount: '',
    category: ''
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Determine which endpoint to hit based on form data
    if (formData.title && formData.date && formData.agenda) {
      // Create meeting record
      await fetch('/api/record-management-service/meetings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: formData.title,
          date: formData.date,
          agenda: formData.agenda
        })
      });
    } else if (formData.description && formData.meetingId && formData.amount && formData.category) {
      // Create financial record
      await fetch('/api/record-management-service/financial-records', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          description: formData.description,
          meetingId: formData.meetingId,
          amount: Number(formData.amount),
          date: formData.date,
          category: formData.category
        })
      });
    }
  };

  return (
    <div className="record-form-page">
      <h2>Add New Record</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="title">Title:</label>
          <input
            type="text"
            id="title"
            name="title"
            value={formData.title}
            onChange={handleInputChange}
          />
        </div>

        <div>
          <label htmlFor="date">Date:</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleInputChange}
          />
        </div>

        <div>
          <label htmlFor="agenda">Agenda:</label>
          <textarea
            id="agenda"
            name="agenda"
            value={formData.agenda}
            onChange={handleInputChange}
          />
        </div>

        <div>
          <label htmlFor="meetingId">Meeting ID:</label>
          <input
            type="text"
            id="meetingId"
            name="meetingId"
            value={formData.meetingId}
            onChange={handleInputChange}
          />
        </div>

        <div>
          <label htmlFor="description">Description:</label>
          <input
            type="text"
            id="description"
            name="description"
            value={formData.description}
            onChange={handleInputChange}
          />
        </div>

        <div>
          <label htmlFor="amount">Amount:</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={formData.amount}
            onChange={handleInputChange}
          />
        </div>

        <div>
          <label htmlFor="category">Category:</label>
          <input
            type="text"
            id="category"
            name="category"
            value={formData.category}
            onChange={handleInputChange}
          />
        </div>

        <button type="submit">Submit</button>
      </form>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Equipment {
  id: number;
  name: string;
  description: string;
  quantity: number;
}

export function EquipmentManagementPage() {
  const [equipmentList, setEquipmentList] = useState<Equipment[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [formData, setFormData] = useState<Omit<Equipment, 'id'>>({ 
    name: '', 
    description: '', 
    quantity: 0 
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch equipment list
  useEffect(() => {
    fetch('/api/equipment-api')
      .then(response => response.json())
      .then(data => setEquipmentList(data));
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'quantity' ? Number(value) : value
    });
  };

  // Add new equipment
  const handleAddEquipment = () => {
    fetch('/api/equipment-api', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(formData)
    })
    .then(response => response.json())
    .then(newItem => {
      setEquipmentList([...equipmentList, newItem]);
      setFormData({ name: '', description: '', quantity: 0 });
    });
  };

  // Update existing equipment
  const handleUpdateEquipment = () => {
    if (editingId === null) return;

    fetch(`/api/equipment-api/${editingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: formData.name,
        description: formData.description,
        quantity: formData.quantity
      })
    })
    .then(response => response.json())
    .then(updatedItem => {
      setEquipmentList(equipmentList.map(item => 
        item.id === editingId ? updatedItem : item
      ));
      setEditingId(null);
      setFormData({ name: '', description: '', quantity: 0 });
    });
  };

  // Delete equipment
  const handleDeleteEquipment = (id: number) => {
    fetch(`/api/equipment-api/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setEquipmentList(equipmentList.filter(item => item.id !== id));
    });
  };

  // Filter equipment based on search term and category
  const filteredEquipment = equipmentList.filter(item => 
    (item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
     item.description.toLowerCase().includes(searchTerm.toLowerCase())) &&
    (categoryFilter === '' || item.description.toLowerCase().includes(categoryFilter.toLowerCase()))
  );

  return (
    <div className="equipment-management-page">
      <h1>Equipment Management</h1>

      <div className="form-section">
        <h2>{editingId ? 'Edit Equipment' : 'Add New Equipment'}</h2>
        <input
          type="text"
          name="name"
          placeholder="Equipment Name"
          value={formData.name}
          onChange={handleInputChange}
        />
        <textarea
          name="description"
          placeholder="Description"
          value={formData.description}
          onChange={handleInputChange}
        />
        <input
          type="number"
          name="quantity"
          placeholder="Quantity"
          value={formData.quantity}
          onChange={handleInputChange}
        />
        <button onClick={editingId ? handleUpdateEquipment : handleAddEquipment}>
          {editingId ? 'Update Equipment' : 'Add Equipment'}
        </button>
      </div>

      <div className="search-section">
        <input
          type="text"
          placeholder="Search by name or description"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
        <input
          type="text"
          placeholder="Filter by category"
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
        />
      </div>

      <div className="equipment-list">
        <h2>Equipment Inventory</h2>
        {filteredEquipment.length === 0 ? (
          <p>No equipment found.</p>
        ) : (
          <ul>
            {filteredEquipment.map(item => (
              <li key={item.id}>
                <strong>{item.name}</strong> - {item.description} ({item.quantity} units)
                <button onClick={() => {
                  setEditingId(item.id);
                  setFormData({ 
                    name: item.name, 
                    description: item.description, 
                    quantity: item.quantity 
                  });
                }}>
                  Edit
                </button>
                <button onClick={() => handleDeleteEquipment(item.id)}>Delete</button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Booking {
  id: number;
  patientName: string;
  pickupLocation: string;
  destination: string;
  status: string;
}

interface Patient {
  id: number;
  name: string;
  email: string;
  phone: string;
  medicalHistory: string;
  emergencyContacts: string;
}

export function StaffBookingSystem() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [newBooking, setNewBooking] = useState({
    patientName: '',
    pickupLocation: '',
    destination: '',
  });
  const [selectedBookingId, setSelectedBookingId] = useState<number | null>(null);
  const [updatedStatus, setUpdatedStatus] = useState('');

  // Fetch bookings
  useEffect(() => {
    fetch('/api/booking-service')
      .then(res => res.json())
      .then(data => setBookings(data));
  }, []);

  // Fetch patients
  useEffect(() => {
    fetch('/api/patient-service')
      .then(res => res.json())
      .then(data => setPatients(data));
  }, []);

  const handleCreateBooking = () => {
    fetch('/api/booking-service', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        patientName: newBooking.patientName,
        pickupLocation: newBooking.pickupLocation,
        destination: newBooking.destination,
      }),
    })
      .then(res => res.json())
      .then(createdBooking => {
        setBookings([...bookings, createdBooking]);
        setNewBooking({ patientName: '', pickupLocation: '', destination: '' });
      });
  };

  const handleUpdateBookingStatus = () => {
    if (selectedBookingId === null) return;

    fetch(`/api/booking-service/${selectedBookingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: updatedStatus }),
    })
      .then(res => res.json())
      .then(updatedBooking => {
        setBookings(
          bookings.map(booking =>
            booking.id === selectedBookingId ? updatedBooking : booking
          )
        );
        setSelectedBookingId(null);
        setUpdatedStatus('');
      });
  };

  return (
    <div className="staff-booking-system">
      <h1>Staff Booking System</h1>

      <div>
        <h2>Create New Booking</h2>
        <input
          type="text"
          placeholder="Patient Name"
          value={newBooking.patientName}
          onChange={e => setNewBooking({ ...newBooking, patientName: e.target.value })}
        />
        <input
          type="text"
          placeholder="Pickup Location"
          value={newBooking.pickupLocation}
          onChange={e => setNewBooking({ ...newBooking, pickupLocation: e.target.value })}
        />
        <input
          type="text"
          placeholder="Destination"
          value={newBooking.destination}
          onChange={e => setNewBooking({ ...newBooking, destination: e.target.value })}
        />
        <button onClick={handleCreateBooking}>Create Booking</button>
      </div>

      <div>
        <h2>Manage Bookings</h2>
        <ul>
          {bookings.map(booking => (
            <li key={booking.id}>
              <strong>{booking.patientName}</strong> - {booking.pickupLocation} to {booking.destination}
              <br />
              Status: {booking.status}
              <br />
              <label>
                Update Status:
                <input
                  type="text"
                  value={updatedStatus}
                  onChange={e => setUpdatedStatus(e.target.value)}
                />
              </label>
              <button onClick={() => {
                setSelectedBookingId(booking.id);
                handleUpdateBookingStatus();
              }}>
                Update Status
              </button>
            </li>
          ))}
        </ul>
      </div>

      <div>
        <h2>Patient Details</h2>
        <ul>
          {patients.map(patient => (
            <li key={patient.id}>
              <strong>{patient.name}</strong>
              <br />
              Email: {patient.email}
              <br />
              Phone: {patient.phone}
              <br />
              Medical History: {patient.medicalHistory}
              <br />
              Emergency Contacts: {patient.emergencyContacts}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Booking {
  id: number;
  patientName: string;
  pickupLocation: string;
  destination: string;
  status: string;
}

interface PatientInfo {
