              <p>Pickup: {booking.pickupLocation}</p>
              <p>Destination: {booking.destination}</p>
              <p>Status: {booking.status}</p>
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h2>Request New Booking</h2>
        <form onSubmit={submitBooking}>
          <input
            type="text"
            name="patientName"
            placeholder="Your Name"
            value={newBooking.patientName}
            onChange={handleBookingChange}
            required
          />
          <input
            type="text"
            name="pickupLocation"
            placeholder="Pickup Location"
            value={newBooking.pickupLocation}
            onChange={handleBookingChange}
            required
          />
          <input
            type="text"
            name="destination"
            placeholder="Destination"
            value={newBooking.destination}
            onChange={handleBookingChange}
            required
          />
          <button type="submit">Submit Booking</button>
        </form>
      </section>

      <section>
        <h2>Personal Information</h2>
        <form onSubmit={submitPersonalInfo}>
          <input
            type="text"
            name="name"
            placeholder="Full Name"
            value={patientInfo.name}
            onChange={handleInfoChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Email Address"
            value={patientInfo.email}
            onChange={handleInfoChange}
            required
          />
          <input
            type="tel"
            name="phone"
            placeholder="Phone Number"
            value={patientInfo.phone}
            onChange={handleInfoChange}
            required
          />
          <textarea
            name="medicalHistory"
            placeholder="Medical History"
            value={patientInfo.medicalHistory}
            onChange={handleInfoChange}
          />
          <textarea
            name="emergencyContacts"
            placeholder="Emergency Contacts"
            value={patientInfo.emergencyContacts}
            onChange={handleInfoChange}
          />
