}

interface Equipment {
  id: number;
  name: string;
  description: string;
  quantity: number;
}

interface Student {
  id: number;
  name: string;
}

export function LendingRecordsPage() {
  const [loanRecords, setLoanRecords] = useState<LoanRecord[]>([]);
  const [equipmentList, setEquipmentList] = useState<Equipment[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStatus, setSelectedStatus] = useState<'all' | 'active' | 'returned'>('all');

  useEffect(() => {
    // Simulate fetching loan records
    const mockLoanRecords: LoanRecord[] = [
      { id: 1, studentId: 101, equipmentId: 201, dueDate: '2023-12-15', status: 'active' },
      { id: 2, studentId: 102, equipmentId: 202, dueDate: '2023-12-10', status: 'returned' },
      { id: 3, studentId: 103, equipmentId: 203, dueDate: '2023-12-20', status: 'active' },
    ];

    // Simulate fetching equipment list
    const mockEquipment: Equipment[] = [
      { id: 201, name: 'Laptop', description: 'MacBook Pro', quantity: 5 },
      { id: 202, name: 'Projector', description: 'Epson X1', quantity: 3 },
      { id: 203, name: 'Tablet', description: 'iPad Air', quantity: 8 },
    ];

    // Simulate fetching students
    const mockStudents: Student[] = [
      { id: 101, name: 'John Doe' },
      { id: 102, name: 'Jane Smith' },
      { id: 103, name: 'Bob Johnson' },
    ];

    setLoanRecords(mockLoanRecords);
    setEquipmentList(mockEquipment);
    setStudents(mockStudents);
  }, []);

  const handleReturn = async (loanId: number) => {
    // Corrected API call using PUT /api/lending-api/loans/:id/status
    await fetch(`/api/lending-api/loans/${loanId}/status`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ status: 'returned' }),
    });

    // Update local state
    setLoanRecords(prev => 
      prev.map(loan => 
        loan.id === loanId ? { ...loan, status: 'returned' } : loan
      )
    );
  };

  const filteredRecords = loanRecords.filter(record => {
    const matchesSearch = students.find(s => s.id === record.studentId)?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          equipmentList.find(e => e.id === record.equipmentId)?.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = selectedStatus === 'all' || record.status === selectedStatus;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">Lending Records</h1>

      <div className="mb-4 flex space-x-4">
        <input
          type="text"
          placeholder="Search by user or equipment..."
          className="border rounded px-3 py-2"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />

        <select
          className="border rounded px-3 py-2"
          value={selectedStatus}
          onChange={(e) => setSelectedStatus(e.target.value as 'all' | 'active' | 'returned')}
        >
          <option value="all">All Statuses</option>
          <option value="active">Active</option>
          <option value="returned">Returned</option>
        </select>
      </div>

      <div className="overflow-x-auto">
        <table className="min-w-full bg-white border border-gray-200">
          <thead>
            <tr className="bg-gray-100">
              <th className="py-2 px-4 border-b text-left">Student</th>
              <th className="py-2 px-4 border-b text-left">Equipment</th>
              <th className="py-2 px-4 border-b text-left">Due Date</th>
              <th className="py-2 px-4 border-b text-left">Status</th>
              <th className="py-2 px-4 border-b text-left">Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredRecords.map(record => {
              const student = students.find(s => s.id === record.studentId);
              const equipment = equipmentList.find(e => e.id === record.equipmentId);

              return (
                <tr key={record.id}>
                  <td className="py-2 px-4 border-b">{student?.name || 'Unknown Student'}</td>
                  <td className="py-2 px-4 border-b">{equipment?.name || 'Unknown Equipment'}</td>
                  <td className="py-2 px-4 border-b">{record.dueDate}</td>
                  <td className="py-2 px-4 border-b">{record.status}</td>
                  <td className="py-2 px-4 border-b">
                    {record.status === 'active' && (
                      <button 
                        onClick={() => handleReturn(record.id)}
                        className="bg-green-500 text-white px-3 py-1 rounded hover:bg-green-600"
                      >
                        Mark as Returned
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

