import { useState, useEffect } from 'react';

interface Customer {
  id: number;
  name: string;
  service: string;
  status: 'waiting' | 'in-progress' | 'completed';
}

export function CustomerListPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerService, setNewCustomerService] = useState('');

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      const response = await fetch('/api/queue-management-api/queue');
      const data = await response.json();
      setCustomers(data);
    } catch (error) {
      console.error('Failed to fetch customers:', error);
    }
  };

  const handleAddCustomer = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newCustomerName.trim() || !newCustomerService.trim()) return;

    try {
      const response = await fetch('/api/queue-management-api/queue', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: newCustomerName,
          service: newCustomerService,
        }),
      });

      if (response.ok) {
        await fetchCustomers();
        setNewCustomerName('');
        setNewCustomerService('');
      }
    } catch (error) {
      console.error('Failed to add customer:', error);
    }
  };

  const updateCustomerStatus = async (id: number, status: Customer['status']) => {
    try {
      const response = await fetch(`/api/queue-management-api/queue/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status }),
      });

      if (response.ok) {
        await fetchCustomers();
      }
    } catch (error) {
      console.error('Failed to update customer status:', error);
    }
  };

  return (
    <div className="customer-list-page">
      <h1>Customer Queue</h1>

      <form onSubmit={handleAddCustomer}>
        <input
          type="text"
          placeholder="Customer Name"
          value={newCustomerName}
          onChange={(e) => setNewCustomerName(e.target.value)}
          required
        />
        <input
          type="text"
          placeholder="Service Type"
          value={newCustomerService}
          onChange={(e) => setNewCustomerService(e.target.value)}
          required
        />
        <button type="submit">Add Customer</button>
      </form>

      <ul>
        {customers.map((customer) => (
          <li key={customer.id}>
            <span>{customer.name} - {customer.service}</span>
            <select
              value={customer.status}
              onChange={(e) => updateCustomerStatus(customer.id, e.target.value as Customer['status'])}
            >
              <option value="waiting">Waiting</option>
              <option value="in-progress">In Progress</option>
              <option value="completed">Completed</option>
            </select>
          </li>
        ))}
      </ul>
    </div>
  );
}

