import { useState, useEffect } from 'react';

interface Tag {
  id: string;
  name: string;
}

export function TagManagementPage() {
  const [tags, setTags] = useState<Tag[]>([]);
  const [newTagName, setNewTagName] = useState('');
  const [editingTagId, setEditingTagId] = useState<string | null>(null);
  const [editTagName, setEditTagName] = useState('');

  useEffect(() => {
    fetchTags();
  }, []);

  const fetchTags = async () => {
    try {
      const response = await fetch('/api/tags-api');
      const data = await response.json();
      setTags(data);
    } catch (error) {
      console.error('Failed to fetch tags:', error);
    }
  };

  const handleCreateTag = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTagName.trim()) return;

    try {
      const response = await fetch('/api/tags-api', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ name: newTagName.trim() }),
      });

      if (response.ok) {
        const createdTag = await response.json();
        setTags([...tags, createdTag]);
        setNewTagName('');
      }
    } catch (error) {
      console.error('Failed to create tag:', error);
    }
  };

  const handleUpdateTag = async (id: string, newName: string) => {
    try {
      const response = await fetch(`/api/tags-api/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ name: newName.trim() }),
      });

      if (response.ok) {
        const updatedTag = await response.json();
        setTags(tags.map(tag => tag.id === id ? updatedTag : tag));
        setEditingTagId(null);
        setEditTagName('');
      }
    } catch (error) {
      console.error('Failed to update tag:', error);
    }
  };

  const handleDeleteTag = async (id: string) => {
    try {
      const response = await fetch(`/api/tags-api/${id}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        setTags(tags.filter(tag => tag.id !== id));
      }
    } catch (error) {
      console.error('Failed to delete tag:', error);
    }
  };

  return (
    <div className="tag-management-page">
      <h1>Tag Management</h1>

      <form onSubmit={handleCreateTag}>
        <input
          type="text"
          value={newTagName}
          onChange={(e) => setNewTagName(e.target.value)}
          placeholder="Enter new tag name"
          required
        />
        <button type="submit">Add Tag</button>
      </form>

      <ul>
        {tags.map(tag => (
          <li key={tag.id}>
            {editingTagId === tag.id ? (
              <>
                <input
                  type="text"
                  value={editTagName}
                  onChange={(e) => setEditTagName(e.target.value)}
                  autoFocus
                />
                <button onClick={() => handleUpdateTag(tag.id, editTagName)}>Save</button>
                <button onClick={() => setEditingTagId(null)}>Cancel</button>
              </>
            ) : (
              <>
                <span>{tag.name}</span>
                <button onClick={() => {
                  setEditingTagId(tag.id);
                  setEditTagName(tag.name);
                }}>Edit</button>
                <button onClick={() => handleDeleteTag(tag.id)}>Delete</button>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

