export function InventoryManagement() {
  const [products, setProducts] = useState<Product[]>([]);
  const [name, setName] = useState('');
  const [price, setPrice] = useState('');
  const [stock, setStock] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editName, setEditName] = useState('');
  const [editPrice, setEditPrice] = useState('');
  const [editStock, setEditStock] = useState('');

  // Fetch products from API
  useEffect(() => {
    fetch('/api/inventory-management-service/inventory')
      .then(response => response.json())
      .then(data => setProducts(data));
  }, []);

  // Add new product
  const handleAddProduct = () => {
    if (!name || !price || !stock) return;

    fetch('/api/inventory-management-service/inventory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name,
        price: Number(price),
        stock: Number(stock)
      })
    })
      .then(response => response.json())
      .then(newProduct => {
        setProducts([...products, newProduct]);
        setName('');
        setPrice('');
        setStock('');
      });
  };

  // Update existing product
  const handleUpdateProduct = () => {
    if (!editingId || !editName || !editPrice || !editStock) return;

    fetch(`/api/inventory-management-service/inventory/${editingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: editName,
        price: Number(editPrice),
        stock: Number(editStock)
      })
    })
      .then(response => response.json())
      .then(updatedProduct => {
        setProducts(products.map(p => p.id === editingId ? updatedProduct : p));
        setEditingId(null);
      });
  };

  // Delete product
  const handleDeleteProduct = (id: number) => {
    fetch(`/api/inventory-management-service/inventory/${id}`, {
      method: 'DELETE'
    })
      .then(() => {
        setProducts(products.filter(p => p.id !== id));
      });
  };

  return (
    <div className="inventory-management">
      <h1>Inventory Management</h1>

      {/* Add Product Form */}
      <div>
        <h2>Add New Product</h2>
        <input
          type="text"
          placeholder="Product Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          type="number"
          placeholder="Price"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
        />
        <input
          type="number"
          placeholder="Stock"
          value={stock}
          onChange={(e) => setStock(e.target.value)}
        />
        <button onClick={handleAddProduct}>Add Product</button>
      </div>

      {/* Product List */}
      <div>
        <h2>Product List</h2>
        {products.length === 0 ? (
          <p>No products found.</p>
        ) : (
          <ul>
            {products.map(product => (
              <li key={product.id}>
                {product.name} - ${product.price} - Stock: {product.stock}
                <button onClick={() => {
                  setEditingId(product.id);
                  setEditName(product.name);
                  setEditPrice(product.price.toString());
                  setEditStock(product.stock.toString());
                }}>Edit</button>
                <button onClick={() => handleDeleteProduct(product.id)}>Delete</button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Edit Product Form */}
      {editingId && (
        <div>
          <h2>Edit Product</h2>
          <input
            type="text"
            placeholder="Product Name"
            value={editName}
            onChange={(e) => setEditName(e.target.value)}
          />
          <input
            type="number"
            placeholder="Price"
            value={editPrice}
            onChange={(e) => setEditPrice(e.target.value)}
          />
          <input
            type="number"
            placeholder="Stock"
            value={editStock}
            onChange={(e) => setEditStock(e.target.value)}
          />
          <button onClick={handleUpdateProduct}>Update Product</button>
          <button onClick={() => setEditingId(null)}>Cancel</button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Customer {
  id: number;
  name: string;
  email: string;
  phone: string;
}

export function CustomerManagement() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch customers on component mount
  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      const response = await fetch('/api/customer-management-service/customers');
      const data = await response.json();
      setCustomers(data);
    } catch (error) {
      console.error('Failed to fetch customers:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId !== null) {
      // Update existing customer
      try {
        await fetch(`/api/customer-management-service/customers/${editingId}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ name, email, phone }),
        });

        // Refresh customer list
        fetchCustomers();

        // Reset form
        setName('');
        setEmail('');
        setPhone('');
        setEditingId(null);
      } catch (error) {
        console.error('Failed to update customer:', error);
      }
    } else {
      // Add new customer
      try {
        await fetch('/api/customer-management-service/customers', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ name, email, phone }),
        });

        // Refresh customer list
        fetchCustomers();

        // Reset form
        setName('');
        setEmail('');
        setPhone('');
      } catch (error) {
        console.error('Failed to add customer:', error);
      }
    }
  };

  const handleEdit = (customer: Customer) => {
    setName(customer.name);
    setEmail(customer.email);
    setPhone(customer.phone);
    setEditingId(customer.id);
  };

  const handleDelete = async (id: number) => {
    try {
      await fetch(`/api/customer-management-service/customers/${id}`, {
        method: 'DELETE',
      });

      // Refresh customer list
      fetchCustomers();
    } catch (error) {
      console.error('Failed to delete customer:', error);
    }
  };

  return (
    <div className="customer-management">
      <h1>Customer Management</h1>

      <form onSubmit={handleSubmit}>
        <div>
          <input
            type="text"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
        </div>
        <div>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </div>
        <div>
          <input
            type="tel"
            placeholder="Phone"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            required
          />
        </div>
        <button type="submit">
          {editingId !== null ? 'Update Customer' : 'Add Customer'}
        </button>
      </form>

      <h2>Customer List</h2>
      <ul>
        {customers.map((customer) => (
          <li key={customer.id}>
            <span>{customer.name} - {customer.email} - {customer.phone}</span>
            <button onClick={() => handleEdit(customer)}>Edit</button>
            <button onClick={() => handleDelete(customer.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

