import { useState, useEffect } from 'react';

interface Student {
  id: number;
  name: string;
  email: string;
  grade: string;
}

interface Payment {
  id: number;
  studentId: number;
  amount: number;
  date: string;
  status: string;
}

export function StudentManagement() {
  const [students, setStudents] = useState<Student[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [newStudent, setNewStudent] = useState({
    name: '',
    email: '',
    grade: ''
  });

  useEffect(() => {
    // Fetch students
    fetch('/api/student-api/students')
      .then(res => res.json())
      .then(data => setStudents(data));

    // Fetch payments
    fetch('/api/payment-api/payments')
      .then(res => res.json())
      .then(data => setPayments(data));
  }, []);

  const handleAddStudent = () => {
    fetch('/api/student-api/students', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: newStudent.name,
        email: newStudent.email,
        grade: newStudent.grade
      })
    })
    .then(res => res.json())
    .then(student => {
      setStudents([...students, student]);
      setNewStudent({ name: '', email: '', grade: '' });
    });
  };

  const handleUpdateStudent = (id: number, updatedFields: Partial<Student>) => {
    fetch(`/api/student-api/students/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updatedFields)
    })
    .then(res => res.json())
    .then(updatedStudent => {
      setStudents(students.map(s => s.id === id ? updatedStudent : s));
    });
  };

  const handleDeleteStudent = (id: number) => {
    fetch(`/api/student-api/students/${id}`, {
      method: 'DELETE'
    });
    setStudents(students.filter(s => s.id !== id));
  };

  const filteredStudents = students.filter(student =>
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    student.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="student-management">
      <h1>Student Management</h1>

      <div className="add-student">
        <h2>Add New Student</h2>
        <input
          type="text"
          placeholder="Name"
          value={newStudent.name}
          onChange={(e) => setNewStudent({...newStudent, name: e.target.value})}
        />
        <input
          type="email"
          placeholder="Email"
          value={newStudent.email}
          onChange={(e) => setNewStudent({...newStudent, email: e.target.value})}
        />
        <input
          type="text"
          placeholder="Grade"
          value={newStudent.grade}
          onChange={(e) => setNewStudent({...newStudent, grade: e.target.value})}
        />
        <button onClick={handleAddStudent}>Add Student</button>
      </div>

      <div className="search">
        <input
          type="text"
          placeholder="Search students..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="student-list">
        <h2>Student Records</h2>
        {filteredStudents.map(student => (
          <div key={student.id} className="student-card">
            <h3>{student.name}</h3>
            <p>Email: {student.email}</p>
            <p>Grade: {student.grade}</p>
            <button onClick={() => handleDeleteStudent(student.id)}>Delete</button>
          </div>
        ))}
      </div>

      <div className="payment-history">
        <h2>Payment History</h2>
        {payments.map(payment => (
          <div key={payment.id} className="payment-card">
            <p>Student ID: {payment.studentId}</p>
            <p>Amount: ${payment.amount}</p>
            <p>Date: {payment.date}</p>
            <p>Status: {payment.status}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

