          type="date"
          value={newBatch.startDate}
          onChange={(e) => setNewBatch({...newBatch, startDate: e.target.value})}
          required
        />
        <input
          type="date"
          value={newBatch.endDate}
          onChange={(e) => setNewBatch({...newBatch, endDate: e.target.value})}
          required
        />
        <input
          type="number"
