                  <input
                    type="date"
                    value={editForm.startDate}
                    onChange={(e) => setEditForm({...editForm, startDate: e.target.value})}
                    required
                  />
                  <input
                    type="date"
                    value={editForm.endDate}
                    onChange={(e) => setEditForm({...editForm, endDate: e.target.value})}
                    required
                  />
                  <input
                    type="number"
                    value={editForm.maxStudents || ''}
                    onChange={(e) => setEditForm({...editForm, maxStudents: Number(e.target.value)})}
                    required
                  />
                  <button type="submit">Save</button>
                  <button type="button" onClick={() => setEditingBatchId(null)}>Cancel</button>
                </form>
              ) : (
                <>
                  <h3>{batch.name}</h3>
                  <p>Start Date: {batch.startDate}</p>
                  <p>End Date: {batch.endDate}</p>
                  <p>Max Students: {batch.maxStudents}</p>
                  <button onClick={() => {
                    setEditingBatchId(batch.id);
                    setEditForm({
                      name: batch.name,
                      startDate: batch.startDate,
                      endDate: batch.endDate,
                      maxStudents: batch.maxStudents
                    });
                  }}>Edit</button>
                  <button onClick={() => handleDeleteBatch(batch.id)}>Delete</button>
                </>
              )}
            </div>
          ))
        ) : (
          <p>No batches found.</p>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Student {
  id: number;
  name: string;
  email: string;
  batchId: number | null;
}

interface Batch {
  id: number;
  name: string;
  startDate: string;
  endDate: string;
  maxStudents: number;
}

export function StudentManagementPage() {
  const [students, setStudents] = useState<Student[]>([]);
  const [batches, setBatches] = useState<Batch[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [newStudent, setNewStudent] = useState({
    name: '',
    email: '',
    batchId: ''
  });
  const [editingStudentId, setEditingStudentId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    name: '',
    email: '',
    batchId: ''
  });

  // Fetch students and batches
  useEffect(() => {
    fetch('/api/student-api/students')
      .then(res => res.json())
      .then(data => setStudents(data));

    fetch('/api/batch-api/batches')
      .then(res => res.json())
      .then(data => setBatches(data));
  }, []);

  const filteredStudents = students.filter(student =>
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    student.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleCreateStudent = () => {
    if (!newStudent.name || !newStudent.email) return;

    fetch('/api/student-api/students', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: newStudent.name,
        email: newStudent.email,
        batchId: newStudent.batchId ? Number(newStudent.batchId) : null
      })
    })
      .then(res => res.json())
      .then(createdStudent => {
        setStudents([...students, createdStudent]);
        setNewStudent({ name: '', email: '', batchId: '' });
      });
  };

  const handleUpdateStudent = () => {
    if (!editingStudentId || !editForm.name || !editForm.email) return;

    fetch(`/api/student-api/students/${editingStudentId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: editForm.name,
        email: editForm.email,
        batchId: editForm.batchId ? Number(editForm.batchId) : null
      })
    })
      .then(res => res.json())
      .then(updatedStudent => {
        setStudents(students.map(s => s.id === editingStudentId ? updatedStudent : s));
        setEditingStudentId(null);
      });
  };

  const handleDeleteStudent = (id: number) => {
    fetch(`/api/student-api/students/${id}`, { method: 'DELETE' })
      .then(() => setStudents(students.filter(s => s.id !== id)));
  };

  return (
    <div className="student-management-page">
      <h1>Student Management</h1>

      {/* Search */}
      <input
        type="text"
        placeholder="Search students..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      {/* Create Student Form */}
      <div>
        <h2>Create New Student</h2>
        <input
          type="text"
          placeholder="Name"
          value={newStudent.name}
          onChange={(e) => setNewStudent({...newStudent, name: e.target.value})}
        />
        <input
          type="email"
          placeholder="Email"
          value={newStudent.email}
          onChange={(e) => setNewStudent({...newStudent, email: e.target.value})}
        />
        <select
          value={newStudent.batchId}
          onChange={(e) => setNewStudent({...newStudent, batchId: e.target.value})}
        >
          <option value="">Select Batch</option>
          {batches.map(batch => (
            <option key={batch.id} value={batch.id}>{batch.name}</option>
          ))}
        </select>
        <button onClick={handleCreateStudent}>Add Student</button>
      </div>

      {/* Student List */}
      <div>
        <h2>Students</h2>
        {filteredStudents.length === 0 ? (
          <p>No students found.</p>
        ) : (
          <ul>
            {filteredStudents.map(student => (
              <li key={student.id}>
                {editingStudentId === student.id ? (
                  <>
                    <input
                      type="text"
                      value={editForm.name}
                      onChange={(e) => setEditForm({...editForm, name: e.target.value})}
                    />
                    <input
                      type="email"
                      value={editForm.email}
                      onChange={(e) => setEditForm({...editForm, email: e.target.value})}
                    />
                    <select
                      value={editForm.batchId}
                      onChange={(e) => setEditForm({...editForm, batchId: e.target.value})}
                    >
                      <option value="">Select Batch</option>
                      {batches.map(batch => (
                        <option key={batch.id} value={batch.id}>{batch.name}</option>
                      ))}
                    </select>
                    <button onClick={handleUpdateStudent}>Save</button>
                    <button onClick={() => setEditingStudentId(null)}>Cancel</button>
                  </>
                ) : (
                  <>
                    <span>{student.name} - {student.email}</span>
                    <button onClick={() => {
                      setEditingStudentId(student.id);
                      setEditForm({
                        name: student.name,
                        email: student.email,
                        batchId: student.batchId?.toString() || ''
                      });
                    }}>Edit</button>
                    <button onClick={() => handleDeleteStudent(student.id)}>Delete</button>
                  </>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Order {
  id: number;
  customerName: string;
  items: string[];
  totalAmount: number;
  status: string;
}

export function OrdersPage() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [filteredOrders, setFilteredOrders] = useState<Order[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  useEffect(() => {
    // Simulate fetching orders from API
    const mockOrders: Order[] = [
      { id: 1, customerName: 'John Doe', items: ['Pizza', 'Salad'], totalAmount: 25.99, status: 'pending' },
      { id: 2, customerName: 'Jane Smith', items: ['Burger', 'Fries'], totalAmount: 18.50, status: 'completed' },
      { id: 3, customerName: 'Bob Johnson', items: ['Sushi', 'Miso Soup'], totalAmount: 42.75, status: 'pending' },
    ];
    setOrders(mockOrders);
    setFilteredOrders(mockOrders);
  }, []);

  useEffect(() => {
    let result = orders;

    if (searchTerm) {
      result = result.filter(order => 
        order.customerName.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (statusFilter !== 'all') {
      result = result.filter(order => order.status === statusFilter);
    }

    setFilteredOrders(result);
  }, [searchTerm, statusFilter, orders]);

  const handleStatusChange = (orderId: number, newStatus: string) => {
    // Simulate updating order status via API
    fetch(`/api/order-service/${orderId}/status`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ status: newStatus }),
    });

    setOrders(orders.map(order => 
      order.id === orderId ? { ...order, status: newStatus } : order
    ));
  };

  return (
    <div className="orders-page">
      <h1>Catering Orders</h1>

      <div className="filters">
        <input
          type="text"
          placeholder="Search by customer name..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="status-filter"
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      <table className="orders-table">
        <thead>
          <tr>
            <th>Customer Name</th>
            <th>Items</th>
            <th>Total Amount</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredOrders.map(order => (
            <tr key={order.id}>
              <td>{order.customerName}</td>
              <td>{order.items.join(', ')}</td>
              <td>${order.totalAmount.toFixed(2)}</td>
              <td>{order.status}</td>
              <td>
                <select
                  value={order.status}
                  onChange={(e) => handleStatusChange(order.id, e.target.value)}
                  className="status-dropdown"
                >
                  <option value="pending">Pending</option>
                  <option value="completed">Completed</option>
                  <option value="cancelled">Cancelled</option>
                </select>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Participant {
  id: string;
  userId: string;
  name: string;
  steps: number;
}

interface Competition {
  id: string;
  name: string;
  startDate: string;
  endDate: string;
  description: string;
  participants: Participant[];
}

export function CompetitionManagement() {
  const [competitions, setCompetitions] = useState<Competition[]>([]);
  const [currentCompetition, setCurrentCompetition] = useState<Omit<Competition, 'id' | 'participants'>>({ 
    name: '', 
    startDate: '', 
    endDate: '', 
    description: '' 
  });
  const [newParticipant, setNewParticipant] = useState({ userId: '', name: '' });
  const [selectedCompetitionId, setSelectedCompetitionId] = useState<string | null>(null);

  useEffect(() => {
    fetchCompetitions();
  }, []);

  const fetchCompetitions = async () => {
    try {
      const response = await fetch('/api/competition-service/competitions');
      const data = await response.json();
      setCompetitions(data);
    } catch (error) {
      console.error('Failed to fetch competitions:', error);
    }
  };

  const handleCreateCompetition = async () => {
    try {
      const response = await fetch('/api/competition-service/competitions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(currentCompetition)
      });
      const createdCompetition = await response.json();
      setCompetitions([...competitions, createdCompetition]);
      setCurrentCompetition({ name: '', startDate: '', endDate: '', description: '' });
    } catch (error) {
      console.error('Failed to create competition:', error);
    }
  };

  const handleAddParticipant = async (competitionId: string) => {
    if (!newParticipant.userId || !newParticipant.name) return;
    try {
      const response = await fetch(`/api/competition-service/competitions/${competitionId}/participants`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newParticipant)
      });
      const updatedCompetition = await response.json();
      setCompetitions(competitions.map(c => c.id === competitionId ? updatedCompetition : c));
      setNewParticipant({ userId: '', name: '' });
    } catch (error) {
      console.error('Failed to add participant:', error);
    }
  };

  const handleUpdateCompetition = async (id: string) => {
    try {
      const response = await fetch(`/api/competition-service/competitions/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(currentCompetition)
      });
      const updatedCompetition = await response.json();
      setCompetitions(competitions.map(c => c.id === id ? updatedCompetition : c));
    } catch (error) {
      console.error('Failed to update competition:', error);
    }
  };

  return (
    <div>
      <h1>Competition Management</h1>

      <div>
        <h2>Create New Competition</h2>
        <input 
          type="text" 
          placeholder="Name" 
          value={currentCompetition.name}
          onChange={(e) => setCurrentCompetition({...currentCompetition, name: e.target.value})}
        />
        <input 
          type="date" 
          value={currentCompetition.startDate}
          onChange={(e) => setCurrentCompetition({...currentCompetition, startDate: e.target.value})}
        />
        <input 
          type="date" 
          value={currentCompetition.endDate}
          onChange={(e) => setCurrentCompetition({...currentCompetition, endDate: e.target.value})}
        />
        <textarea 
          placeholder="Description" 
          value={currentCompetition.description}
          onChange={(e) => setCurrentCompetition({...currentCompetition, description: e.target.value})}
        />
        <button onClick={handleCreateCompetition}>Create Competition</button>
      </div>

      <div>
        <h2>Existing Competitions</h2>
        {competitions.map(comp => (
          <div key={comp.id}>
            <h3>{comp.name}</h3>
            <p>{comp.description}</p>
            <p>Start: {comp.startDate}</p>
            <p>End: {comp.endDate}</p>

            <div>
              <h4>Add Participant</h4>
              <input 
                type="text" 
                placeholder="User ID" 
                value={newParticipant.userId}
                onChange={(e) => setNewParticipant({...newParticipant, userId: e.target.value})}
              />
              <input 
                type="text" 
                placeholder="Name" 
                value={newParticipant.name}
                onChange={(e) => setNewParticipant({...newParticipant, name: e.target.value})}
              />
              <button onClick={() => handleAddParticipant(comp.id)}>Add Participant</button>
            </div>

            <div>
              <h4>Participants</h4>
              {comp.participants && comp.participants.length > 0 ? (
                <ul>
                  {comp.participants.map(p => (
                    <li key={p.id}>{p.name} ({p.steps} steps)</li>
                  ))}
                </ul>
              ) : (
                <p>No participants yet.</p>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface StockItem {
  id: number;
  name: string;
  quantity: number;
  unit: string;
}

export function StockManagementPage() {
  const [stockItems, setStockItems] = useState<StockItem[]>([]);
  const [newItem, setNewItem] = useState({
    name: '',
    quantity: 0,
    unit: ''
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    name: '',
    quantity: 0,
    unit: ''
  });

  useEffect(() => {
    fetchStockItems();
  }, []);

  const fetchStockItems = async () => {
    try {
      const response = await fetch('/api/stock-management-service/stock');
      const data = await response.json();
      setStockItems(data);
    } catch (error) {
      console.error('Failed to fetch stock items:', error);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/stock-management-service/stock', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: newItem.name,
          quantity: newItem.quantity,
          unit: newItem.unit
        })
      });

      if (response.ok) {
        await fetchStockItems();
        setNewItem({
          name: '',
          quantity: 0,
          unit: ''
        });
      }
    } catch (error) {
      console.error('Failed to add item:', error);
    }
  };

  const handleUpdateItem = async (id: number) => {
    try {
      const response = await fetch(`/api/stock-management-service/stock/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: editForm.name,
          quantity: editForm.quantity,
          unit: editForm.unit
        })
      });

      if (response.ok) {
        await fetchStockItems();
        setEditingId(null);
      }
    } catch (error) {
      console.error('Failed to update item:', error);
    }
  };

  const handleDeleteItem = async (id: number) => {
    try {
      const response = await fetch(`/api/stock-management-service/stock/${id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        await fetchStockItems();
      }
    } catch (error) {
      console.error('Failed to delete item:', error);
    }
  };

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">Stock Management</h1>

      <div className="mb-8 p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-4">Add New Item</h2>
        <form onSubmit={handleAddItem} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
            <input
              type="text"
              value={newItem.name}
              onChange={(e) => setNewItem({...newItem, name: e.target.value})}
              className="w-full p-2 border border-gray-300 rounded"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Quantity</label>
            <input
              type="number"
              value={newItem.quantity}
              onChange={(e) => setNewItem({...newItem, quantity: Number(e.target.value)})}
              className="w-full p-2 border border-gray-300 rounded"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Unit</label>
            <input
              type="text"
              value={newItem.unit}
              onChange={(e) => setNewItem({...newItem, unit: e.target.value})}
              className="w-full p-2 border border-gray-300 rounded"
              required
            />
          </div>

          <button
            type="submit"
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            Add Item
          </button>
        </form>
      </div>

      <div className="p-4 bg-white rounded shadow">
        <h2 className="text-xl font-semibold mb-4">Current Stock</h2>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Name</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
