import { useState, useEffect } from 'react';

interface Bill {
  id: number;
  customerId: number;
  amount: number;
  status: string;
  date: string;
}

export function BillsManagement() {
  const [bills, setBills] = useState<Bill[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingBill, setEditingBill] = useState<Bill | null>(null);
  const [formData, setFormData] = useState<Omit<Bill, 'id'>>({ 
    customerId: 0,
    amount: 0,
    status: '',
    date: ''
  });

  useEffect(() => {
    fetchBills();
  }, []);

  const fetchBills = async () => {
    try {
      const response = await fetch('/api/api-server/bills');
      const data = await response.json();
      setBills(data);
      setLoading(false);
    } catch (error) {
      console.error('Failed to fetch bills:', error);
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'customerId' || name === 'amount' ? Number(value) : value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingBill) {
      // Update existing bill
      const response = await fetch(`/api/api-server/bills/${editingBill.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customerId: formData.customerId,
          amount: formData.amount,
          status: formData.status,
          date: formData.date
        })
      });

      if (response.ok) {
        fetchBills();
        setEditingBill(null);
        setFormData({ customerId: 0, amount: 0, status: '', date: '' });
      }
    } else {
      // Create new bill
      const response = await fetch('/api/api-server/bills', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customerId: formData.customerId,
          amount: formData.amount,
          status: formData.status,
          date: formData.date
        })
      });

      if (response.ok) {
        fetchBills();
        setFormData({ customerId: 0, amount: 0, status: '', date: '' });
      }
    }
  };

  const handleEdit = (bill: Bill) => {
    setEditingBill(bill);
    setFormData({
      customerId: bill.customerId,
      amount: bill.amount,
      status: bill.status,
      date: bill.date
    });
  };

  const handleCancel = () => {
    setEditingBill(null);
    setFormData({ customerId: 0, amount: 0, status: '', date: '' });
  };

  if (loading) {
    return <div>Loading bills...</div>;
  }

  return (
    <div>
      <h1>Bills Management</h1>

      <form onSubmit={handleSubmit}>
        <div>
          <label>Customer ID:</label>
          <input
            type="number"
            name="customerId"
            value={formData.customerId}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label>Amount:</label>
          <input
            type="number"
            name="amount"
            value={formData.amount}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label>Status:</label>
          <input
            type="text"
            name="status"
            value={formData.status}
            onChange={handleInputChange}
            required
          />
        </div>

        <div>
          <label>Date:</label>
          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleInputChange}
            required
          />
        </div>

        <button type="submit">
          {editingBill ? 'Update Bill' : 'Add Bill'}
        </button>

        {editingBill && (
          <button type="button" onClick={handleCancel}>Cancel</button>
        )}
      </form>

      <h2>All Bills</h2>
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Customer ID</th>
            <th>Amount</th>
            <th>Status</th>
            <th>Date</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {bills.map(bill => (
            <tr key={bill.id}>
              <td>{bill.id}</td>
              <td>{bill.customerId}</td>
              <td>{bill.amount}</td>
              <td>{bill.status}</td>
              <td>{bill.date}</td>
              <td>
                <button onClick={() => handleEdit(bill)}>Edit</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Request {
  id: number;
  item: string;
  quantity: number;
  status: string;
}

export function UserDashboard() {
  const [requests, setRequests] = useState<Request[]>([]);
  const [newItem, setNewItem] = useState('');
  const [newQuantity, setNewQuantity] = useState('');

  useEffect(() => {
    // Fetch user requests
    fetch('/api/requests-api/requests')
      .then(response => response.json())
      .then(data => setRequests(data));
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Submit new request using correct API endpoint and field names
    fetch('/api/requests-api/requests', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        item: newItem,
        quantity: Number(newQuantity),
        status: 'pending'
      }),
    })
    .then(response => response.json())
    .then(data => {
      setRequests([...requests, data]);
      setNewItem('');
      setNewQuantity('');
    });
  };

  return (
    <div className="user-dashboard">
      <h1>Office Supplies Request Dashboard</h1>

      <h2>Your Requests</h2>
      <ul>
