export function MeasurementTrackingPage() {
  const [measurements, setMeasurements] = useState<Measurement[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState<number | null>(null);
  const [newMeasurement, setNewMeasurement] = useState({
    customerId: '',
    chest: '',
    waist: '',
    hips: '',
    sleeve: '',
    length: ''
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    customerId: '',
    chest: '',
    waist: '',
    hips: '',
    sleeve: '',
    length: ''
  });

  // Fetch customers and measurements
  useEffect(() => {
    fetch('/api/customer-api')
      .then(res => res.json())
      .then(data => setCustomers(data));

    fetch('/api/measurement-api')
      .then(res => res.json())
      .then(data => setMeasurements(data));
  }, []);

  // Filter measurements based on search term
  const filteredMeasurements = measurements.filter(measurement => {
    const customer = customers.find(c => c.id === measurement.customerId);
    return customer?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
           measurement.chest.toString().includes(searchTerm) ||
           measurement.waist.toString().includes(searchTerm);
  });

  const handleAddMeasurement = () => {
    if (!newMeasurement.customerId) return;

    fetch('/api/measurement-api', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        customerId: Number(newMeasurement.customerId),
        chest: Number(newMeasurement.chest),
        waist: Number(newMeasurement.waist),
        hips: Number(newMeasurement.hips),
        sleeve: Number(newMeasurement.sleeve),
        length: Number(newMeasurement.length)
      })
    })
    .then(res => res.json())
    .then(data => {
      setMeasurements([...measurements, data]);
      setNewMeasurement({
        customerId: '',
        chest: '',
        waist: '',
        hips: '',
        sleeve: '',
        length: ''
      });
    });
  };

  const handleUpdateMeasurement = () => {
    if (editingId === null) return;

    fetch(`/api/measurement-api/${editingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        customerId: Number(editForm.customerId),
        chest: Number(editForm.chest),
        waist: Number(editForm.waist),
        hips: Number(editForm.hips),
        sleeve: Number(editForm.sleeve),
        length: Number(editForm.length)
      })
    })
    .then(res => res.json())
    .then(data => {
      setMeasurements(measurements.map(m => m.id === editingId ? data : m));
      setEditingId(null);
    });
  };

  const handleDeleteMeasurement = (id: number) => {
    fetch(`/api/measurement-api/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setMeasurements(measurements.filter(m => m.id !== id));
    });
  };

  return (
    <div className="measurement-tracking-page">
      <h1>Measurement Tracking</h1>

      <div className="add-measurement-section">
        <h2>Add New Measurement</h2>
        <div className="form-group">
          <label>Customer:</label>
          <select
            value={newMeasurement.customerId}
            onChange={(e) => setNewMeasurement({...newMeasurement, customerId: e.target.value})}
          >
            <option value="">Select Customer</option>
            {customers.map(customer => (
              <option key={customer.id} value={customer.id}>{customer.name}</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label>Chest (cm):</label>
          <input
            type="number"
            value={newMeasurement.chest}
            onChange={(e) => setNewMeasurement({...newMeasurement, chest: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Waist (cm):</label>
          <input
            type="number"
            value={newMeasurement.waist}
            onChange={(e) => setNewMeasurement({...newMeasurement, waist: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Hips (cm):</label>
          <input
            type="number"
            value={newMeasurement.hips}
            onChange={(e) => setNewMeasurement({...newMeasurement, hips: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Sleeve (cm):</label>
          <input
            type="number"
            value={newMeasurement.sleeve}
            onChange={(e) => setNewMeasurement({...newMeasurement, sleeve: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Length (cm):</label>
          <input
            type="number"
            value={newMeasurement.length}
            onChange={(e) => setNewMeasurement({...newMeasurement, length: e.target.value})}
          />
        </div>

        <button onClick={handleAddMeasurement}>Add Measurement</button>
      </div>

      <div className="search-section">
        <h2>Search Measurements</h2>
        <input
          type="text"
          placeholder="Search by customer name or measurement..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
