          <div className="form-group">
            <label>Waist (cm):</label>
            <input
              type="number"
              value={editForm.waist}
              onChange={(e) => setEditForm({...editForm, waist: e.target.value})}
            />
          </div>

          <div className="form-group">
            <label>Hips (cm):</label>
            <input
              type="number"
              value={editForm.hips}
