    e.preventDefault();

    // Send login request to the correct API endpoint
    const response = await fetch('/api/authentication-service/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        username,
        password,
      }),
    });

    if (!response.ok) {
      throw new Error('Login failed');
    }

    // In a real app, you would handle the response (e.g., store token)
    console.log('Login successful');
  };

  return (
    <div className="login-container">
      <h2>Staff Login</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="username">Username:</label>
          <input
            id="username"
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
        </div>
        <div>
          <label htmlFor="password">Password:</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </div>
        <button type="submit">Login</button>
      </form>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Prescription {
  id: number;
  patientId: number;
  medication: string;
  dosage: string;
  frequency: string;
  status: 'pending' | 'dispensed' | 'cancelled';
}

export function PrescriptionManagement() {
  const [prescriptions, setPrescriptions] = useState<Prescription[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredPrescriptions, setFilteredPrescriptions] = useState<Prescription[]>([]);

  useEffect(() => {
    // Simulate fetching prescriptions
    const mockPrescriptions: Prescription[] = [
      { id: 1, patientId: 101, medication: 'Ibuprofen', dosage: '200mg', frequency: 'Every 6 hours', status: 'pending' },
      { id: 2, patientId: 102, medication: 'Amoxicillin', dosage: '500mg', frequency: 'Every 8 hours', status: 'dispensed' },
      { id: 3, patientId: 103, medication: 'Lisinopril', dosage: '10mg', frequency: 'Once daily', status: 'cancelled' },
    ];
    setPrescriptions(mockPrescriptions);
    setFilteredPrescriptions(mockPrescriptions);
  }, []);

  useEffect(() => {
    const filtered = prescriptions.filter(prescription => 
      prescription.medication.toLowerCase().includes(searchTerm.toLowerCase()) ||
      prescription.patientId.toString().includes(searchTerm)
    );
    setFilteredPrescriptions(filtered);
  }, [searchTerm, prescriptions]);

  const handleDispense = async (id: number) => {
    // Use the correct API endpoint for dispensing
    await fetch(`/api/dispensing-api/dispense`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ prescriptionId: id, quantity: 1 })
    });

    // Update UI
    setPrescriptions(prev => 
      prev.map(p => p.id === id ? { ...p, status: 'dispensed' } : p)
    );
  };

  const handleCancel = async (id: number) => {
    // Use the correct API endpoint for updating prescription status
    await fetch(`/api/prescription-api/prescriptions/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        patientId: 0, 
        medication: '', 
        dosage: '', 
        frequency: '', 
        status: 'cancelled'
      })
    });

    // Update UI
    setPrescriptions(prev => 
      prev.map(p => p.id === id ? { ...p, status: 'cancelled' } : p)
    );
  };

  return (
    <div className="prescription-management">
      <h1>Prescription Management</h1>

      <div className="search-container">
        <input
          type="text"
          placeholder="Search by medication or patient ID"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />
      </div>

      <div className="prescription-list">
        {filteredPrescriptions.map(prescription => (
          <div key={prescription.id} className="prescription-item">
            <div className="prescription-details">
              <strong>Patient ID:</strong> {prescription.patientId}<br />
              <strong>Medication:</strong> {prescription.medication}<br />
              <strong>Dosage:</strong> {prescription.dosage}<br />
              <strong>Frequency:</strong> {prescription.frequency}<br />
              <strong>Status:</strong> {prescription.status}<br />
            </div>

            <div className="prescription-actions">
              {prescription.status === 'pending' && (
                <button onClick={() => handleDispense(prescription.id)}>Dispense</button>
              )}

              {prescription.status === 'pending' && (
                <button onClick={() => handleCancel(prescription.id)}>Cancel</button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Medication {
  id: number;
  name: string;
  stockLevel: number;
  alertThreshold: number;
}

export function MedicationInventory() {
  const [medications, setMedications] = useState<Medication[]>([]);
  const [newMedication, setNewMedication] = useState({
    name: '',
    stockLevel: 0,
    alertThreshold: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchMedications();
  }, []);

  const fetchMedications = async () => {
    try {
      const response = await fetch('/api/inventory-api');
      const data = await response.json();
      setMedications(data);
      setLoading(false);
    } catch (error) {
      console.error('Failed to fetch medications:', error);
      setLoading(false);
    }
  };

  const handleAddMedication = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/inventory-api', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: newMedication.name,
          stockLevel: newMedication.stockLevel,
          alertThreshold: newMedication.alertThreshold
        })
      });

      if (response.ok) {
        await fetchMedications();
        setNewMedication({
          name: '',
          stockLevel: 0,
          alertThreshold: 0
        });
      }
    } catch (error) {
      console.error('Failed to add medication:', error);
    }
  };

  const handleUpdateStock = async (id: number, stockLevel: number) => {
    try {
      const response = await fetch(`/api/inventory-api/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: medications.find(m => m.id === id)?.name || '',
          stockLevel,
          alertThreshold: medications.find(m => m.id === id)?.alertThreshold || 0
        })
      });

      if (response.ok) {
        await fetchMedications();
      }
    } catch (error) {
      console.error('Failed to update stock:', error);
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="medication-inventory">
      <h1>Medication Inventory</h1>

      <div className="add-medications">
        <h2>Add New Medication</h2>
        <form onSubmit={handleAddMedication}>
          <div>
            <label htmlFor="name">Name:</label>
            <input
              type="text"
              id="name"
              value={newMedication.name}
              onChange={(e) => setNewMedication({...newMedication, name: e.target.value})}
              required
            />
          </div>

          <div>
            <label htmlFor="stockLevel">Stock Level:</label>
            <input
              type="number"
              id="stockLevel"
              value={newMedication.stockLevel}
              onChange={(e) => setNewMedication({...newMedication, stockLevel: Number(e.target.value)})}
              required
            />
          </div>

          <div>
            <label htmlFor="alertThreshold">Alert Threshold:</label>
            <input
              type="number"
              id="alertThreshold"
              value={newMedication.alertThreshold}
              onChange={(e) => setNewMedication({...newMedication, alertThreshold: Number(e.target.value)})}
              required
            />
          </div>

          <button type="submit">Add Medication</button>
        </form>
      </div>

      <div className="inventory-list">
        <h2>Current Inventory</h2>
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Stock Level</th>
              <th>Alert Threshold</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {medications.map((medication) => (
              <tr key={medication.id}>
                <td>{medication.name}</td>
                <td>
                  <input
                    type="number"
                    value={medication.stockLevel}
                    onChange={(e) => handleUpdateStock(medication.id, Number(e.target.value))}
                  />
                </td>
                <td>{medication.alertThreshold}</td>
                <td>
                  {medication.stockLevel <= medication.alertThreshold && (
                    <span style={{ color: 'red' }}>Low Stock!</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
